INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999239409', 'Pedaleira Polo TSI 18/.. Automático Aço Inox - Não fura o pedal', 'Gravação em relevo antiderrapante; Aparência esportiva e personalizada; Modelagem sob medida; Não fura os pedais originais; Instalação simples feita em minutos; ITENS INCLUSOS: 1 pedaleira para acelerador 1 pedaleira para freio DESCRIÇÃO: A textura do aço escovado e a gravação em baixo relevo aumentam a aderência dos pedais garantindo mais esportividade na pilotagem. A instalação é simples e pode ser realizada em poucos minutos, pois as pedaleiras são fixadas com fita-dupla face 3M de alta performance. Este método de fixação foi testado e aperfeiçoado exaustivamente até chegarmos numa fixação firme e duradoura, o que é imprescindível para um local com tanto atrito e movimento. Projetadas especificamente para instalação no Polo TSI com câmbio automático, estas pedaleiras cobrem os pedais originais com perfeição. A sola dos seus calçados normalmente estão sujas, contendo todo tipo de sujeira, o que colabora para o rápido desgaste dos pedais do seu Polo TSI. Por serem produzidas em aço inoxidável elas nunca perderão o brilho. Instale este conjunto de pedaleiras que além de proteger os pedais contra o desgaste também vai proporcional um visual realmente esportivo. VEÍCULOS COMPATÍVEIS: Volkswagen: • Polo 2018 Automático • Polo 2019 Automático • Polo 2020 Automático • Polo 2021 Automático • Polo 2022 Automático • Virtus 2018 Automático • Virtus 2019 Automático • Virtus 2020 Automático • Virtus 2021 Automático • Virtus 2022 Automático DADOS TÉCNICOS PEDALEIRA: Matéria prima: aço inox 304; Espessura: 1,2 mm; Acabamento: escovado; Fita dupla face: 3M VHB; GARANTIA: 1 ano', 160.27, 160.27, NULL, 'Hobbies & Collections > Souvenirs > Others', 'https://cf.shopee.com.br/file/1176a9375b7e652f5044cb7e9768f414', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1103244663%2F21999239409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
