INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797117008', 'Batedeira Mondial 400W B-44 3,6 Litros', 'A batedeira Prática B-44-B da Mondial é a escolha para você que quer performance e praticidade em um só aparelho. Seus 400W de potência e tigela com capacidade para 3,6L proporcionam mais eficiência na hora de bater suas massas. Aproveite suas 3 velocidades e também a função turbo para preparar suas receitas de forma mais ágil e completa. Os batedores são de aço inox, oferecendo mais resistência e durabilidade ao produto e se soltam facilmente quando o botão ejetor é pressionado. Dimensões: Altura: 24 cm Largura: 33 cm Profundidade: 24 cm Peso: 2 kg Garantia do fornecedor de 12 meses.', 156.9, 156.9, NULL, 'Home & Living > Kitchenware > Whisks & Beaters', 'https://cf.shopee.com.br/file/sg-11134201-7rbmd-lnud3zwhcgmp42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082747237%2F23797117008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
