INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257531572', 'Tênis de Led Infantil Gatinho Cintilante Pampili', 'Tênis de led infantil é a escolha perfeita para as meninas brilharem com conforto e muita fofura. Com acabamento contilante, o modelo traz bigodes de gatinho bordados no fechamento e um visual moderno que combina com a escola, passeios e festinhas. O calce fácil com fita aderente facilita a rotina e incentiva a autonomia, deixando tudo mais prático e estiloso. Por dentro, o conforto é completo, o modelo conta com colarinho super macio, forro absorvente de suor e palmilha anatômica que juntos cuidam dos pezinhos com suavidade. O destaque fica no solado translúcido antiderrapante com luzes de led brancas, que acendem ao caminhar em ritmos diferentes, deixando cada passo mais divertido. Aposte! Combine com vestido de tule ou shortinho com camiseta estampada para um look fashion e moderno. Para festas e celebrações, use com acessórios brilhantes para um visual digno de estrela.', 269.9, 215.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820mg-mmsxhjnsa5ttba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547100334%2F58257531572', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
