INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698188472', 'Conjunto Curto Laço Feminino Bebê Lilica Ripilica', 'Um look completo e perfeito para um visual charmoso: O Conjunto Lilica Ripilica promete ser o preferido das meninas que amam estilo desde cedo! Confeccionado em tecido de viscose sarjado, a peça é garantia de conforto e frescor para todos os momentos. O laço é tendência nos looks da estação e traz um destaque especial para a blusa. Além disso, a blusa possui mangas curtas em modelagem soltinha, detalhe em pregas e fechamento em botão nas costas, facilitando a hora de vestir. A calça conta com elástico no cós, modelagem wide leg e detalhe em pregas, dando mais amplitude à peça. O conjunto também traz a assinatura da marca em uma etiqueta metalizada. Aposta certa nessa estação, sua pequena vai ficar ainda mais linda com o look! • Conjunto com blusa e calça • Manga curta soltinha • Fechamento em botão • Destaque para o laço • Elástico no cós • Detalhe em pregas • Tecido de viscose sarjado', 379.0, 189.5, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7raum-maokbkkslxme20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F20698188472', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
