INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5686437037', 'Pinador Pneumático 18ga Af506 Makita - Original com 1 Ano de Garantia', 'CARACTERÍSTICAS: - O Pinador Pneumático AF506 da Makita serve para montagem de móveis, painéis, assoalhos (Compensados. MDF, MDP, madeira). - Para a utilização do Pinador AF506 é necessário um compressor de no mínimo 120 libras. - O AF506 da Makita é leve, compacto e trabalha com pinos Tipo F com capacidade para 100 pinos. - Pinador de novo designer, mais leve e ergonômico; - Ajuste de profundidade; - Batedor emborrachado protege a superfície da madeira; - Exaustão multidirecional à 360º; - Magazine com mostrador; - Cabo emborrachado; - Presilha para suporte em cintos; - Tampão de engate rápido: fácil remoção/ajuste dos pinos sem necessidade de desparafusar a caixa da máquina. ESPECIFICAÇÕES: - Marca: Makita - Ref.: AF506 - Pressão do ar: 0.49 - 0.83MPa (70-120PSI); - Comprimento: 15 - 50mm (19/32" - 2"); - Calibragem: 18 (Tipo F); - Capacidade: 100 pinos; - Dimensões (C x L x A): 250 x 70 x 256mm; - Peso: 1.3 kg.', 760.0, 760.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/e25d3429bdf0d6326bbfb58e0141caa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F5686437037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
