INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098178451', 'Kit Pistão e Anel 0,50 - GM Celta 1.0 8V VHC 2006 2007 2008 2009 Gasolina - Metal Leve SPA9186050', 'CONTEÚDO DA EMBALAGEM (KIT): 01 JOGO DE PISTÕES E ANÉIS 0,50 - MAHLE / METAL LEVE CÓD. SPA9186050 SENDO: 04 PISTÕES 04 PINOS 01 JOGO DE ANÉIS DE SEGMENTO PRODUTOS NOVOS, ORIGINAIS, COM GARANTIA E NOTA FISCAL. APLICAÇÃO: *** APENAS PARA CARROS A GASOLINA COM MOTOR 1.0, 8V, VHC*** GM CELTA (SPIRIT / LIFE / SUPER) 1.0 8V VHC - 2002 / 2009 - GASOLINA GM CLASSIC (SPIRIT / LIFE / SUPER / MPFI) 1.0 8V VHC - 2003 / 2007 - GASOLINA GM CORSA (GL / NEW JOY / NEW MAX / NEW PREMIUM) 1.0 8V VHC - 2002 / 2009 - GASOLINA GM NEW CLASSIC 1.0 8V 2015 - 2015 - GASOLINA ATENÇÃO: A RESPONSABILIDADE DA COMPATIBILIDADE DO PRODUTO E SUA APLICAÇÃO É DO COMPRADOR; NÃO NOS RESPONSABILIZAMOS POR PREJUÍZOS ADVINDOS DA APLICAÇÃO INCORRETA DO PRODUTO. CONSULTE O FABRICANTE DO SEU EQUIPAMENTO E CONFIRME A COMPATIBILIDADE COM O INSTALADOR. A MARTINS AUTOPEÇAS DISPÕE DE PEÇAS AUTOMOTIVAS PARA TODA A LINHA LEVE E MÉDIA DE VEÍCULOS, SE NÃO ENCONTRAR O QUE PROCURA, DEIXE UMA PERGUNTA E RESPONDEREMOS O MAIS BREVE POSSÍVEL.', 733.35, 733.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rblg-m5sh6qf2l4nyb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F538200526%2F23098178451', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12649392938', 'Tampa Lateral Pro Tork Moto Honda Biz 100 125 Ks Es / +125 Ex 2011 2012 2013 2014 2015 2016', 'As carenagens e peças plásticas Pro Tork são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricadas em ABS 100% virgem, são extremamente resistentes aos raios UV, tornando-se assim o melhor custo-benefício do mercado. Características: - Marca: Pro Tork; - Modelo: Original; - Tonalidade de cores semelhante ao original; - Valor referente ao par; - Moto compatível: Biz 100 KS/ES 2012 a 2013 / Biz 125 KS/ES 2011 a 2015 / Biz+ 125 EX 2016 (Confira a relação de cores anos abaixo). Aplicação: Biz 100 KS/ES: - Lilás: 2012 e 2013; - Preto: 2012 e 2013; Biz 125 KS/ES: - Lilás: 2012 e 2013; - Prata Ibiúna: 2012; - Preto: 2011, 2012, 2013 e 2014; - Rosa Metálico: 2011; - Verde Metálico: 2011; - Vermelho Pimenta: 2013, 2014 e 2015. Biz+ 125 EX: - Preto: 2016. Atenção! Devido ao desgaste da pintura da motocicleta com o passar do tempo, pode haver uma pequena divergência na tonalidade das cores. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada. Sportbay - Seu Esporte, Nossa Paixão.', 248.32, 129.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbikrdr7jbzscb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F12649392938', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098050351', 'Tapete de Atividades Musical com Piano Interativo Ginásio com Som e Luzes', 'TAPETE INFANTIL DE ATIVIDADES COM PIANO MUSICAL - ATENTU O Tapete Infantil de Atividades Atentu foi desenvolvido para proporcionar momentos de aprendizado, diversão e desenvolvimento desde os primeiros meses de vida. Indicado para bebês a partir de 2 meses, ele conta com um móbile colorido de bichinhos, um piano interativo com luzes brilhantes e um colchão acolchoado para total conforto. CONTEÚDO DA EMBALAGEM: - 1 Tapete de atividades colorido desmontado; - Manual de montagem. ESPECIFICAÇÕES: - Colchão acolchoado; - Arco Colorido Mobile; - Piano que funciona com 3 pilhas AA (não inclusas); - Luzes coloridas no Piano; - Estampa Colorida; - Material: Plástico; - Certificação INMETRO: 011675/2023; - Marca: ATENTU. MEDIDAS DO PRODUTO: - (CxAxL) 73 x 42 x 56 IMPORTANTE: * Garantia: 3 Meses a partir da data de recebimento - para defeitos de fabricação (não cobrimos mau uso). *Todos os Direitos Reservados Em caso de cópia dessa descrição e fotos, os responsáveis serão cobrados de acordo com a Lei (9.610/98) de Direitos Autorais.*', 139.9, 79.9, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6zkl0fib0x3ea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1384111782%2F23098050351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
