INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894657077', 'Capa para Notebook 14" Preta | Sleeve Coca-Cola', 'A Capa para Notebook Sleeve Coca-Cola é a escolha perfeita para quem busca estilo, proteção e conveniência. Ideal para notebooks de 14", oferece proteção superior contra riscos e impactos, graças ao seu interior acolchoado de alta qualidade. Seu design icônico com a logo Coca-Cola garante um visual moderno, enquanto o fechamento em zíper duplo proporciona acesso fácil e seguro. O bolso frontal extra é perfeito para guardar acessórios essenciais como cabos, fones e adaptadores. Uma combinação perfeita de funcionalidade e estilo para seu notebook! Especificações: Design exclusivo e licenciado Coca-Cola, garantindo estilo, autenticidade e alta qualidade Compatível com: notebooks de 14 polegadas Interior acolchoado para uma proteção extra contra riscos e impactos Zíper duplo para fácil abertura e segurança Bolso frontal para organizar acessórios como cabos, carregadores e outros itens essenciais Cor preta, um visual sofisticado e versátil para qualquer situação Garantia: 3 meses Garantia Legal de 3 meses contra defeitos de fabricação. Imagens ilustrativas. As cores podem variar de acordo com o monitor ou lote de fabricação.', 299.9, 129.9, NULL, 'Computers & Accessories > Peripherals & Accessories > Laptop Skins & Covers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh81jj01eoef97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013839557%2F22894657077', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597090176', 'Beijos e croissants - Alt', 'Um romance de arrancar suspiros na Cidade do Amor, perfeito para os fãs de Amor &amp Gelato e Emily em Paris Mia Jenrow sempre soube que seria uma bailarina profissional. Na verdade, o balé está em seu sangue, uma vez que sua tataravó dançou na Opéra de Paris e foi pintada pelo grande artista Edgar Degas. Apesar de sua família dizer que essa história não passa de uma lenda, para Mia é muito mais: é Seu destino. Depois de planejar um verão mágico na França para ir atrás do seu sonho, Mia finalmente chega em Paris, mas logo percebe que tudo pode ser bem mais complicado do que imaginava. Para começar, ela tem uma rival, Avery, que faz de tudo para expor seus erros. E para piorar, o professor de balé é extremamente rígido e exige padrões de perfeição inalcançáveis. E ainda tem Louis. O catastrófico e charmoso Louis, que está doido para mostrar a sua cidade natal para Mia. Ela mal pode esperar para pular na garupa da Vespa do garoto e abraçá-lo pelas costas enquanto passeiam sob as luzes brilhantes da Torre Eiffel. Assim, Mia percebe que o seu verão será muito mais do que treinar passos de balé, afinal, não é à toa que Paris é conhecida como a Cidade do Amor. Beijos e croissants é um romance doce e envolvente, que já teve os direitos vendidos para adaptação audiovisual.', 60.43, 60.43, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rbkp-ln9z0qhou2bm49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22597090176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
