INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44514214464', 'Brinde Skelt Amalfi Sunset - Hidratante Corporal 3g', 'Brinde Skelt Amalfi Sunset - Hidratante Corporal 3g Garante uma pele profundamente hidratada, macia e radiante por até 48 horas. Enriquecido com niacinamida, manteiga de karité e vitamina E, auxilia na restauração da barreira cutânea e estimula a renovação celular. Conta com uma fragrância marcante de notas frutais e florais, que te envolve em uma experiência sensorial sem igual. Conselho de Aplicação Após o banho, com a pele limpa e seca, aplique o produto diariamente sobre todo o corpo e massageie suavemente até a completa absorção pela pele. Reaplique sempre que desejar.', 1084.31, 1084.31, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mqrzclyvka9vee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F44514214464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
