INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19199897008', 'Barrinha de Proteina - 1 Barra 45g Salted Caramel - Eat Clean', 'A barra de proteína vegana da Eat Clean é a combinação perfeita de pasta de castanha de caju com proteína vegetal, resultando em barrinhas proteicas, cremosas e com um sabor surpreendente. Cada unidade contém 45g com 12g de proteína. 100% à base de plantas, sem açúcar, sem glúten, sem lactose e vegana! Como Tomar Consumir até 2 unidades ao dia ou conforme orientação profissional. Ingredientes Blend proteico (proteína isolada de ervilha, proteína extrusada de ervilha, proteína concentrada de arroz), pasta de castanha-de-caju EAT CLEAN sabor salted caramel, cobertura sabor chocolate meio amargo, ganache sabor chocolate ao leite de coco, maltitol, goma acácia, tâmaras desidratadas, polidextrose, fibra solúvel da mandioca, eritritol, óleo de coco, inulina de chicória, emulsificante (lecitina de girassol - INS 322), aromatizantes naturais, sal rosa do Himalaia, extrato de alecrim e vitamina E. NÃO CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE. ALÉRGICOS: CONTÉM CASTANHA-DE-CAJU. PODE CONTER: AMÊNDOA, AMENDOIM, AVELÃ, CASTANHA-DO-BRASIL, MACADAMIA E NOZES. *Os ingredientes utilizados são veganos e não contêm açúcar adicionado. ...', 25.5, 25.5, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/sg-11134201-824is-mfox39svble5b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F19199897008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298792432', 'Fita Filete Papel Crepe 10,0mmx45m Amarela', 'Descrição Descrição do produto: "ATENÇÃO" Filetes com medidas 2,0mm fazem curvas fechadas. A Fita Crepe é composta por papel crepe na cor amarela, tratado com solução à base de borracha. Aplicação: Quando aplicada em metal, borracha, vidro e partes plásticas, não deixa resíduos de adesivo. Produto resiste até 3 dias em área externa. Neste caso, evitar aplicação sobre borracha. Com esta fita você pode criar o que precisar, desde simples faixas até pinturas onde sejam necessárias varias cores e formas, pois essa fita permite que se faça curvas positivas, negativas cantos, ondas, flames. Características: Material: Papel crepe tratado Adesivo: Borracha Cor: Amarela Largura: 10,0 mm (milímetros) comprimento: 40 metros Marca: Adere Esta fita possui alta flexibilidade e mobilidade que facilitam a aplicação e remoção. Ideal para filetar grandes peças, pois a fita é em rolo continuo. A fita é na cor amarela igual a foto do anúncio este produto pode sofrer variação de largura e comprimento em até 10% Indicada para trabalhos artísticos', 21.5, 21.5, NULL, 'Stationery > School & Office Equipment > Strings & Tapes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mctta23nz4zlea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F492644177%2F22298792432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
