INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891691354', 'DIARIO DE PILAR NO EGITO - PEQUENA ZAHAR', 'Em mais uma emocionante aventura a bordo da rede mágica, Pilar vai viajar para o Egito com seus inseparáveis companheiros Breno e o gatinho Samba. Ao desembarcar inesperadamente no Vale dos Reis, a menina aventureira encontra Tutancâmon, o jovem faraó que foi enterrado vivo num sarcófago e precisa de ajuda para recuperar seu trono. Nas asas da Fênix, os amigos sobrevoam o deserto e vivem experiências inesquecíveis explorando as pirâmides, enfrentando deuses, feras e seres mitológicos. Navegam o rio Nilo em uma feluca ― um barco de madeira com uma única vela ―, visitam o templo de Hórus e conhecem a escrita hieroglífica.Indicado para leitores a partir de 9 anos.', 62.9, 62.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rfg1-m9yjt5px9fah5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F22891691354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
