INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298679915', 'Teclado para Notebook Toshiba Satellite C650', 'Teclado compatível com Toshiba Satellite C650 O teclado compatível com Toshiba Satellite C650 foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Toshiba. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: C650 Moldura: Não se aplica Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC234-TO-0001 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: L655-S5144, C655, L655, L655-S5078, C660, C650, C650 SERIES, L650-SERIES, C655-S5132, L755-SERIES, C655D, L655-S5158, NSK-TN0SV, L655D, C655-S5061, C670, L755-S5214, L655-S5112, L755-S5360, C660-2E9 Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 70.75, 44.99, NULL, 'Computers & Accessories > Desktop Computers > Others', 'https://cf.shopee.com.br/file/sg-11134201-8257v-mqtq1fwgv959b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23298679915', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493338017', 'Fonte Carregador para Notebook Dell Inspiron 3421 7.4mm x 5.0mm', 'Fonte Carregador compatível com Dell Inspiron 3421 19.5V 4.62A 90W A fonte para Dell Inspiron 3421 foi aprovada em rigorosos testes de qualidade e atende todas as exigências do seu equipamento. Possui tecnologia exclusiva de proteção contra excessos de corrente, superaquecimento e curto-circuito. Todas as fontes bringIT possuem 36 meses de garantia contra defeitos de fabricação. E contam com seletor automático de tensão, que permite funcionamento em 110V e 220V. Atenção: Essa é uma fonte bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Para evitar problemas de compatibilidade, por favor verifique as especificações da sua fonte. OUTPUT: DC 19.5V 4.62A 90W Plug: 7.4mm x 5.0mm Caso você não possua a fonte original, você pode encontrar esta informação em seu notebook indicada como INPUT. Itens inclusos: cabo de 1,20m Marca: bringIT Modelo: 3421 Referência: FT043-DE-708 Atenção: Para que essa fonte seja compatível com seu notebook, deverá ter pino e voltagem iguais e a amperagem igual ou maior que a do anúncio. Esse produto é compatível com os notebooks: LA90PM111, PA-12, E5470, 15-5557, 3421, 3450 3500 3550, N4050, E5450, 14Z-5423, 5480, 7520, 14R-5437, 5448, 1450, N5010, AA90PM111, 14-3442, 3560, 15-5547, E5570 Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 115.38, 115.38, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-8259i-mqu69yainqj12c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22493338017', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394182806', 'Par de hastes com dobradiças para Notebook Acer Aspire A515-51-56K6', 'Par de hastes com dobradiças para Notebook Acer Aspire A515-51-56K6 Estas hastes com dobradiças para notebook são a solução para seus problemas com o movimento de abrir e fechar a tampa do seu computador. O produto é novo, feito em material resistente e a embalagem contém duas unidades para montagem e fixação nos lados direito e esquerdo da carcaça do notebook. Com as hastes e dobradiças novas você soluciona alguns problemas: - Dificuldade ao abrir e/ou fechar o notebook - Tampa do notebook está frouxa e/ou mole - Barulho ao abrir e/ou fechar a tampa - Elevação ou rachadura na carcaça do notebook Atenção! É importante verificar a compatibilidade das hastes e dobradiças com o seu modelo de notebook para que sejam exatamente as peças que seu computador precisa. Garantia: 3 meses de garantia contra defeitos de fabricação Referência: HT057-AC-0023', 49.87, 44.88, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mq5924p1rjeq68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23394182806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
