INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998707875', 'Filtro de Oleo Mahle Oc259 Mitsubishi Asx Lancer Outlander Pajero Tr4', 'FILTRO DE ÓLEO LUBRIFICANTE MAHLE OC259 - QUALIDADE ORIGINAL E MÁXIMA PROTEÇÃO PARA O MOTOR O filtro de óleo Mahle OC259 é essencial para manter a lubrificação do motor eficiente e protegida contra impurezas. Com alto desempenho e padrão de qualidade original, é ideal para quem busca segurança, durabilidade e excelente custo-benefício na manutenção do veículo. Filtro blindado de óleo - pronto para uso, fácil instalação Garante filtragem eficiente contra resíduos e partículas nocivas Qualidade OEM Mahle - confiança das montadoras Produto novo, envio imediato com nota fiscal e garantia APLICAÇÃO MITSUBISHI Airtrek / ASX / Colt / Eclipse / Galant / Grandis - 1992 a 2022 Lancer 1.6 / 2.0 Turbo - 1993 a 2016 L200 Triton 3.5 V6 - 2017 a 2018 Outlander 2.0 / 2.3 / 2.4 / 3.0 / PHEV - 2007 a 2022 Pajero TR4 2.0 16V - 2002 a 2022 Space Wagon 2.0 / 2.4 - 1993 a 2004 ESPECIFICAÇÕES TÉCNICAS: Altura: 88mm Diâmetro externo: 67,5mm Rosca: M20 x 1,5 Filtro blindado - aplicação direta ## IMPORTANTE: Em caso de dúvida, antes da compra, informe o número do chassi ou placa do veículo. Isso garante a compatibilidade correta e evita trocas desnecessárias.', 25.48, 25.48, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rdxa-mc89056tsyqod5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1077953334%2F23998707875', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
