INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994543565', 'Bolsa Pequena Infantil Feminina Santorini Lilica Ripilica', 'A bolsa santorini da linha lilica ripilica combina praticidade e charme em um design compacto, perfeito para acompanhar as pequenas em diferentes momentos do dia. Apesar do tamanho reduzido, o modelo comporta com eficiência os itens essenciais da rotina infantil, complementando os looks com estilo e funcionalidade. Com alça regulável em gorgurão, proporciona conforto no uso e se adapta facilmente ao tamanho da criança. Seu formato retangular moderno conta com três divisórias com fechamento em zíper, garantindo organização e segurança no transporte dos pertences. A bolsa santorini é a escolha ideal para unir delicadeza, praticidade e personalidade em um só acessório.', 169.9, 129.9, NULL, 'Women Bags > Crossbody & Shoulder Bags', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg5i5iwqnkzk98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F728423102%2F23994543565', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
