INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11854929456', 'Carcaça Painel Superior Pro Tork YBR 125 2006 2007 2008 Preto', 'A Pro Tork possui uma linha completa de plásticos para que você possa realizar a substituição por um excelente custo x benefício. A linha de painéis contém todos os componentes compatíveis com as principais motos do mercado brasileiro, fabricados nos moldes do original. Especificações: - Fabricada em termoplástico de alta resistência; - Resistente aos raios Ultra Violeta; - Design personalizado e mais resistente; - Mesmo molde do modelo original, não necessita adaptações; - ABS 100% virgem Aplicação: - YBR 125 2006; - YBR 125 2007; - YBR 125 2008. - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação. - Para realizar a instalação, leve sua moto à uma oficina especializada. Nós não nos responsabilizamos por danos causados pela má instalação do produto.', 84.11, 47.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lfgx3jwuuhi69b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F11854929456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397686071', 'Sensor Posição Borboleta Chevrolet Suprema 2.2 1997 Original Gauss', 'Sensor de Posição da Borboleta Chevrolet: Desempenho e Precisão para o seu Motor! Está sentindo que o seu carro não está respondendo como deveria? A marcha lenta está irregular ou o consumo de combustível aumentou? O problema pode estar no sensor de posição da borboleta (TPS). O sensor TPS é um componente crucial para o bom funcionamento do motor. Ele informa à central eletrônica a posição da borboleta de aceleração, permitindo o ajuste correto da injeção de combustível e da ignição. Por que escolher o Sensor de Posição da Borboleta Gauss? A Gauss é reconhecida pela qualidade e durabilidade de seus produtos automotivos. Ao escolher um sensor Gauss, você garante um produto confiável, com alta precisão e excelente desempenho, prolongando a vida útil do seu motor. Aplicação / Compatibilidade: Este sensor de posição da borboleta é compatível com diversos veículos Chevrolet, incluindo: Celta (motores VHC, VHC E, 5N e C10NE): 2001 a 2016 Corsa (motores SOHC MPFI, VHC, BE e NLEV): 1996 a 2011 Omega (motor SOHC MPFI): 1997 a 1998 Suprema 2.2 1997 Códigos de Equivalência: Este sensor é equivalente aos códigos: DELPHI: ICD00123 GM ORIGINAL: 17097102 GM ORIGINAL: 25178872 Dimensões e Peso: Peso 0,021 kg Profundidade 6 cm Altura 4 cm Largura 7 cm Não perca tempo! Garanta o bom funcionamento do seu veículo com o Sensor de Posição da Borboleta Gauss. Adquira já o seu e volte a dirigir com segurança e tranquilidade!', 89.99, 89.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lypmtuhgutd1f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F22397686071', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18707532814', 'Aprofundando a Restauração da Alma | David Kornfield', 'Aprofundando a Restauração da AlmaAtravés de Grupos de Apoio Agora que você deu o primeiro passo A decisão de resgatar a saúde emocional foi um primeiro passo muito importante Ao estudar Introdução à restauração da alma você pôde se conhecer melhor e identificar as áreas de sua vida que precisam ser transformadas Agora um novo e decisivo passo se coloca diante de você David Kornfield assegura que a oportunidade de participar de um grupo de apoio lhe permitirá receber as orientações para a restauração de que tanto precisa e sem a qual a tão desejada transformação interior dificilmente ocorrerá Através de um grupo de apoio você compartilhará as lutas e os desafios com pessoas como você pessoas que estão no mesmo barco Você já sabe que não se trata de um processo brando e indolor mas também descobriu que vale a pena Depende apenas de você de sua decisão de segurar a mão estendida por Jesus sempre pronto a nos resgatar dos vales da sombra da morte Título Aprofundando a Restauração da Alma Subtitulo Através de Grupos de Apoio Autor David Kornfield Páginas 352 Formato 21 x 14 x 1 cm Peso 0 440 kg ISBN 9788573255034 Editora Mundo Cristão', 51.99, 51.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/797ce3ddda60e728654fb968d8fc35e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F18707532814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
