INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259712101', 'Lasanha Sabor Quatro Queijos Sadia', 'A Lasanha Sadia 4 Queijos é perfeita para uma refeição rápida e saborosa, com 4 tipos diferentes de queijo: mussarela, parmesão, gorgonzola e provolone. * Modo de Preparo: 1. Remova totalmente a película plástica da bandeja. 2. Leve a lasanha congelada ao micro-ondas, forno elétrico ou a gás, conforme as indicações: Micro-ondas: 11min (potência alta). Forno elétrico: 45min (210°C). Forno a gás: 50min (200°C). Recomenda-se utilizar luvas térmicas ao retirar o produto do forno.', 19.99, 19.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-825ag-mqnekuk6euizaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58259712101', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
