INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29785458454', 'Caixa de Som Multimídia 10W RMS LED USB P2 Knup KP-RO849', 'Caixa de Som Knup KP-RO849 combina praticidade, estilo e desempenho, sendo perfeita para quem busca uma experiência sonora agradável no dia a dia. Com potência de 10W RMS, entrega um som claro e equilibrado para músicas, vídeos e chamadas, tornando seu uso ideal em ambientes de trabalho, estudo ou lazer. Possui controle de volume integrado para fácil ajuste e conta com alimentação via porta USB 5V, eliminando a necessidade de fontes externas. A conexão de áudio é feita por mini plugue de 3,5mm, garantindo compatibilidade com computadores, notebooks e outros dispositivos. Seu design compacto é complementado por iluminação LED, que adiciona um toque moderno ao seu espaço. ESPECIFICAÇÕES: - Modelo: KP-RO849 - Potência: 10W RMS - Alimentação: 5VDC (via USB) - Frequência: 60Hz – 20kHz - Sensibilidade: 70dB - Compatibilidade: PC e notebook - Controle de volume: Sim - Iluminação: LED - Conexão de áudio: Mini plugue de 3,5mm CONTEÚDO: 1 Caixa de Som', 97.13, 69.5, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/sg-11134201-7rfg4-m966vo3tanzb90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F29785458454', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
