INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898550778', 'Lenço Umedecido Fêmeas Mypetone - 75 Unidades', 'Lenço Umedecido Fêmeas Mypetone - 75 Unidades - Sem álcool; - Higieniza partes mais delicadas do Pet; - Para limpeza a seco de cães e gatos. Detalhes Os Lenços Umedecidos Fêmeas Mypetone, são perfeitos para a higienização e limpeza do seu pet de forma rápida, prática e econômica. Com formulação balanceada promove a limpeza das patas, pele, orelhas, pelos e focinhos deixando um afável perfume. Ideal para ser levado no carro, na bolsa, nas viagens longas, uma ótima opção para situações indesejadas. Dicas Especiais Os Lenços Umedecidos Fêmeas Mypetone, são ótimos para ser usado entre um banho e outro, ou nos dias de temperatura mais frias. Indicação: Cachorros, Gatos Porte/Raça: Raças Pequenas, Raças Médias, Raças Grandes Idade: Filhotes, Adultos, Idosos Composição: Propilenoglicol 1,100 ml Lanolina 0,5ml Cocoamidopropil betaina 1,00ml Polisorbato 20 0,10ml EDTA 0,10ml Fragrância 0,20ml Metilparabeno 0,10ml Apresentação: 75 unidades', 27.9, 11.99, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbe6dyag5v5l63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22898550778', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892307192', 'Areia Sílica Fina Great Pets para Gatos - 1,6 Kg', 'Areia Sílica Fina Great Pets para Gatos - 1,6 Kg ✅ Longa duração: economiza tempo e dinheiro, tornando a manutenção da areia mais conveniente ✅ Ajuda a reduzir odores indesejáveis, mantendo o ambiente mais agradável para o gato e tutor ✅ Alto poder de absorção: prolonga a utilidade da areia, reduzindo a frequência de reposição Detalhes: A Areia Sílica Great Pets Fina para Gatos - 1,6 Kg, se destaca por sua capacidade de reter a urina de forma eficiente e controlar os odores de maneira excepcional. Ela é projetada para durar em média de 30 dias, sem a necessidade de remover os torrões, pois não possui propriedades aglutinantes. Dicas Especiais: Use luvas ao manusear a areia: Ao encher ou esvaziar a bandeja de areia, é recomendável usar luvas para proteger suas mãos. Isso também ajuda a manter a higiene adequada. Indicação: Gatos Porte/Raça: Raças Pequenas, Raças Médias, Raças Grandes Idade: Filhotes, Adultos, Idosos Composição: Sílica Apresentação: Fardo 1,6 Kg', 52.51, 27.87, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdd7nh6i1h4x55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22892307192', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
