INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697446018', 'Paneleiro com 4 Portas Paris Multimóveis MP2185', 'O Paneleiro com 4 Portas Paris Multimóveis MP2185 é produzido em MDP (15mm), com acabamento acetinado (cerca de 20% de brilho) de alta qualidade que agrega elegância ao ambiente. Com 4 portas e puxadores em ABS com acabamento cromado, oferece fácil acesso ao seu interior, onde prateleiras internas proporcionam amplo espaço para armazenar utensílios diversos. Além disso, os pés em polipropileno possuem regulagem de altura, garantindo estabilidade mesmo em superfícies irregulares. Com medidas perfeitas para otimizar o espaço, o Paneleiro Paris da Multimóveis é a escolha certa para quem busca funcionalidade aliada a um design moderno. Conteúdo da Embalagem: 1 (um) Paneleiro 70cm Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 204cm | Largura: 70cm | Profundidade: 32cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. *Obrigatório fixar o paneleiro na parede. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 479.9, 439.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rce2-ltv4rfiui5j7c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23697446018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17688440921', 'Aparador Buffet com Espelho Multimóveis Vegas 4 Portas FG3558 Preto', 'O Aparador Buffet 4 Portas com Espelho Vegas Multimóveis é produzido em MDP, que garante maior durabilidade, facilidade na limpeza, além de um acabamento superior. Com 4 portas, possui acabamento acetinado (cerca de 20% de brilho) e um excelente espaço interno para organizar seus pertences (as prateleiras internas suportam 5 Kg cada e o tampo 10 Kg). Os detalhes com espelhos nas portas deixam o móvel mais requintado, criando um ambiente moderno e charmoso. Os espelhos são de vidro (o que evita que a imagem fique distorcida) e lapidados, ou seja, passam por um processo para que as bordas não fiquem cortantes, o que garante maior segurança. Seu design minimalista, torna o móvel muito versátil, podendo ser utilizado de diversas maneiras e em qualquer ambiente. Conteúdo da Embalagem: 1 (um) aparador 1 (um) kit com 4 espelhos Dimensões do produto montado: Altura: 69,5cm | Largura: 123cm | Profundidade: 32cm *Você pode consultar as medidas internas na imagem técnica do produto. Cores Disponíveis: Branco - Preto - Rustic - Grafite *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. *Obrigatório fixar na parede. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 709.9, 499.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-22100-eu6jg5eh44iv81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F17688440921', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
