INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22411283739', 'Jg Juntas Kit A Kmp Cg 125 2009/ (a)', '🏍️ Jogo de Juntas KIT A KMP para CG 125 - Completo e de Alta Qualidade ✅ Para quem procura: juntas CG 125, kit juntas motor CG 125, jogo juntas KMP CG O melhor Jogo de Juntas KIT A KMP para manutenção completa do motor da sua CG 125. Peças com qualidade superior e durabilidade comprovada. 🔥 Compatibilidade Completa Honda CG 125 Fan (2009 em diante): CG 125 2009 juntas / CG 125 2010 / CG 125 2011 CG 125 2012 kit juntas / CG 125 2013 / CG 125 2014 CG 125 2015 / CG 125 2016 / CG 125 2017 / CG 125 2018 📦 O que você recebe no Kit A Completo ✅ Junta de Cilindro - Vedação perfeita ✅ Junta de Cabeçote - Suporta alta temperatura ✅ Junta Acionador Corrente Comando - Funcionamento suave ✅ Anel Vedação Escape - Sem vazamentos Produto novo - Encaixe perfeito no motor original. ⚙️ Por que escolher o Kit A KMP? Alta resistência térmica = Motor protegido Vedação 100% eficiente = Zero vazamentos Material premium = Maior durabilidade Kit completo = Economia de tempo e dinheiro Juntas motor CG 125 com qualidade líder Reposição juntas CG 125 2010-2018 Kit juntas cabeçote CG 125 testado SKU: 1104035 | EAN: 7899248119055 | OEM: VS05610000002 Manutenção motor CG 125 confiável Juntas KMP CG 125 Fan precisa', 18.0, 18.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-22120-0xhztqg144kvcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F338071078%2F22411283739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54759125394', 'Lovito Vestido Feminino Plus Size Botões Frente DRB172BRL201', '*RECEBA EM 48H EM SÃO PAULO E GRANDE SÃO PAULO. PARA OS DEMAIS ESTADOS RECEBA EM ATÉ 5 DIAS* ✅DESTAQUES -❤️Fresco e confortável -❤️Abotoamento na frente -❤️Mangas curtas ✅DESCRIÇÕES Estampa: Corações Coleção: Ano todo Tamanho Plus: Sim Composição: 100% Poliéster Tipo de Modelagem: Regular Transparência: Não Elasticidade: Não Região de Origem: Brasil ✅REFERÊNCIA DE MODELAGEM A modelo está vestindo: 1XL ✅O PACOTE INCLUI 1 Vestido ✅INTRODUÇÃO À LOVITO A Lovito é uma marca emergente que acredita no poder feminino, comprometida em oferecer opções de roupas elegantes e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertadora e fazer você se sentir bem. Afinal, o melhor acessório para qualquer look é a autoconfiança. ✅NOTAS DE COMPRA Compare suas medidas com nossa tabela disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, entre em contato conosco e responderemos o mais rápido possível.😊', 136.9, 93.9, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/br-11134207-820mg-mpy2cqwcfxmq3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632995122%2F54759125394', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
