INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497850522', 'Pelúcia Hawk de 35cm - Squishmallows', 'Descrição: As novas pelúcias Squismallows chegaram com novos estilos de pelúcia para você poder escolher. Você poderá se divertir com o seu favorito, cada pelúcia é rica em detalhes para deixar qualquer pessoa apaixonada! As novas pelúcias estão muito mais fofas e com novas opções para você escolher a que mais combina com você, sendo perfeitas para quem gosta de uma pelúcia fofinha. Escolha a sua pelúcia favorita para ser sua companheira e crie memórias únicas e especiais com a nova linha de pelúcias de Squishmallows. Características: Marca: Sunny Brinquedos Referência: 4179 Idade recomendada: A partir de 2 meses Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 35 x 25 x 25cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Pelúcia Certificado Inmetro: REGISTRO 008422/2022 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 249.99, 234.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdwe-m0m5usix6a6ae2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F22497850522', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260467095', 'Chinelo Pegada Masculino Plus Size em Couro Preto 533301-03', 'Esse chinelo em couro preto é muito confortável e perfeito para os momentos relax ou para o dia a dia. A linha Duna é conforto extremo aos seus pés, afinal possui uma palmilha que é super macia e se adapta aos contornos do pé, proporcionando muito conforto. Já o solado é leve e flexível e conta com a nossa tecnologia AMORTECH de amortecimento de impactos na região do calcanhar, que garante o máximo de conforto. Os calçados Pegada são produzidos em couro, matéria prima de alta qualidade, que oferece maciez, resistência e muita durabilidade, que pode ser ainda mais prolongada se você manter os cuidados com o couro, como deixar o calçado em um ambiente arejado quando não estiver em uso, limpar com um paninho úmido ou escova de cerdas macias, de forma suave e secar sempre a sombra. Além disso existem alguns cremes específicos para manter ou renovar a aparência do couro. Chinelo Pegada Masculino Plus Size em Couro Preto 533301-03', 179.99, 179.99, NULL, 'Men Shoes > Others', 'https://cf.shopee.com.br/file/sg-11134201-825b5-mq4r10pxnuo187', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817447947%2F58260467095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
