INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56356110414', 'QUIYUM Esfoliante Corporal Com Mel De Abacate 8g – Esfoliação Suave , Hidratação Profunda , Pele E Brilhante Para Equili', 'Esfoliação corporal QUIYUM Abacate Mel 8g – Esfoliação suave, Hidratação profunda, pele suave e brilhante para pele equilibrada a seca Informações básicas do produto Líquido: 8g Validade: 5 anos Ingredientes principais: AVOCADO + MEL, Manteiga de Karité, Ácido Hialurônico, Vitamina C e B5, Aloe Vera Características do produto Esfoliante corporal combina Extratos de Abacate e Mel para hidratar e nutrir profundamente a pele, deixando-a lisa, macia e hidratada. Enriquecido com ácido hialurônico, Vitamina B5, Extrato de vitamina C e aloe vera, refina a textura da pele e fornece umidade duradoura. As partículas esfoliantes suaves oferecem uma ação de esfregar suave, deixando a pele macia e não secadora com um aroma delicado. Sua textura suave garante uma experiência agradável, deixando a pele macia e brilhante. Destaques 🥑 Abacate + Extratos de Mel – Nutre e hidrata profundamente para uma pele macia e flexível 🧴 Enriquecido com manteiga de karité e ácido hialurônico - bloqueia a umidade e melhora a textura da pele ✨ Vitamina C & B5 + Aloe Vera – Clareia e acalma e promove hidratação duradoura 🌸 Partículas esfoliantes suaves – Remove as células mortas da pele sem ressecar, deixando a pele suave e radiante 💧 Fórmula não secadora - Ideal para tipos de pele equilibrada e seca 🛁 Textura suave e aroma delicado - fornece uma experiência luxuosa e semelhante ao spa em casa Modo de usar Aplique uma quantidade generosa na pele úmida e massageie em movimentos circulares, com foco em áreas ásperas.Aplicar uma quantidade generosa na pele úmida e massagear em movimentos circulares, com foco em áreas ásperas. Enxágue bem. Cuidados Apenas para uso externo. Manter fora do alcance de crianças. Não engula. Não use em peles quebradas. EVITE CONTATO COM OS OLHOS. Interrompa o uso se ocorrer sinais de irritação ou erupção cutânea. Loja em local fresco e seco.', 60.0, 32.9, NULL, 'Beauty > Bath & Body Care > Body Scrub & Peel', 'https://cf.shopee.com.br/file/sg-11134201-8260j-mklw6qx68dfq3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F250961519%2F56356110414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
