INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598477231', 'Serra Tico-Tico 14" (350mm) Profissional | Jardinagem e Corte de Árvores', 'Lâmina de serra grande de 14 polegadas (350 mm) O curso de corte extra longo pode facilmente lidar com uma variedade de materiais, tais como madeira, tubos de PVC, metais finos e completar eficientemente tarefas de corte reto e curvo. Design profissional de serra tico-tico As capacidades de corte de curvas flexíveis e precisas tornam-no adequado para processar formas complexas, o que o torna uma ferramenta poderosa para os entusiastas do "faça você mesmo" e para os carpinteiros. Corpo amarelo brilhante A combinação de cores atraente permite a rápida identificação das ferramentas quando são armazenadas, ao mesmo tempo que acrescenta uma sensação de vitalidade à bancada de trabalho. Detalhes humanizados O cabo antiderrapante, o design de troca rápida da lâmina de serra e a função de ajuste multiângulo têm em conta a segurança e a conveniência. 📦 Parâmetros básicos Comprimento da lâmina de serra: 14 polegadas (350 mm) Material: Lâmina de serra em aço de alto teor de carbono Cor: Amarelo brilhante Cenários aplicáveis: carpintaria, decoração, jardinagem, processamento de metais, etc. 💡 Porquê escolher? → Aumento da eficiência: as lâminas de serra de tamanho grande cobrem uma gama mais ampla de necessidades de corte. → Preciso e flexível: o corte curvo é fácil e a produção criativa não exige preocupações. → Durável e fiável: motor de alta qualidade + design ergonómico, duradouro e durável. Seja para reparações domésticas ou projetos profissionais, esta serra tico-tico brilhante e potente pode tornar-se o seu "especialista em corte"! ✨', 99.0, 99.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdlhpkjda2mp4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1442717886%2F22598477231', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593230718', 'Mesa de Escritório Escrivaninha Com Tampo Giratório Para Computador Home Office 2 Gavetas Branca', 'A Mesa Office NT 2060 da Notável Móveis, é um móvel completo que vai te auxiliar nas atividades do home office ou estudos. Com ela, você tem diversas possibilidades de montagem: de canto, montada reta, com o nicho para o lado direito ou esquerdo e você também pode escolher em que lado colocar as gavetas! O tampo de 25 mm é super espaçoso para você organizar itens essenciais ao dia a dia, e as gavetas possuem corrediças metálicas para guardar documentos e demais objetos. Um móvel moderno que vai atender as suas necessidades! Especificações - Comprimento Reta: 200 cm - Comprimento de Canto: 148,6 cm - Largura: 45 cm - Altura: 76 cm - Cor: Branco New - 2 Gavetas - 3 Nichos - Recomendação de Limpeza: Limpar com pano seco para retirar o pó. Não aplicar produtos abrasivos. - Produtos de Enfeite e Eletrônicos Não Estão Inclusos.', 469.9, 469.9, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rdxp-lzfmr8x592x30e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F23593230718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
