INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11970600863', 'Pilhas Recarregáveis Multilaser Aaa 1000Mah 4 Uni. Cb050 1,2 V', 'Pilhas Recarregaveis AAA Multilaser 1000mAH com 4 Unidades - CB050 Composição do material: NIMH, COBRE Tipo de bateria: NI-MH Muitos equipamentos eletrônicos necessitam de pilhas para o seu funcionamento. Como por exemplo as câmeras fotográficas, principalmente as profissionais que não podem ficar descarregadas no meio de um evento. Pensando nisso, trouxemos um kit com 4 pilhas recarregáveis. Faz aproximadamente 1.000 ciclos de recarga e não tem efeito memória. Ideal para câmeras digitais, reprodutores de áudio, rádios intercomunicadores, GPS e outros equipamentos. As pilhas recarregáveis podem ser utilizadas em qualquer aparelho que use o formato AAA. Ficha Técnica Cor: Cinza Pilhas: 4 Pilhas AAA Peso do produto: 50g Largura do produto: 9cm Altura do produto: 4.5cm Comprimento do produto: 14cm Aviso Sobre o Produto: 1000Mah', 41.69, 41.69, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/ce55fb80ce97a1e2809b3bcc4fa4e2da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F11970600863', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
