INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199665948', 'Nutrifer Bisglicinato De Ferro 150mg 60 cápsulas - PREVENT', 'Nutrifer Bisglicinato De Ferro 150mg 60cap - PREVENT Descrição O Nutrifer é um suplemento alimentar em 60 cápsulas de Bisglicinato De Ferro de 150mg da Prevent Pharma Princípio ativo: Bisglicinato De Ferro Apresentação: 60 cápsulas Modo de uso Tomar conforme orientação médica. Advertência Este produto não é medicamento. Não exceda a dose indicada. Mantenha fora do alcance de crianças. Gestantes, nutrizes e crianças até 3 anos devem consultar o médico antes do uso. Conservar longe de luz, calor e umidade. Indicado para maiores de 19 anos. NÃO CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE. Importante Decoração não inclusa. Imagens ilustrativas. Cores podem variar por luminosidade, monitor ou percepção. Dados fornecidos pelo fabricante/fornecedor', 54.99, 34.99, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd52-m7r127z92uew09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F21199665948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11111049171', 'Bolsa Termica Media 13x18 Cm Termogel', 'Substitui a bolsa de água quente tradicional com vantagens: Não vaza, mantém a temperatura por mais tempo que a água e pode ser usada quente ou fria. É Indicada para dores musculares, abdominais, contusões, febre e dor de ouvido.', 29.99, 29.99, NULL, 'Home & Living > Hand Warmers, Hot Water Bags & Ice Bags', 'https://cf.shopee.com.br/file/58f3dbc76fa9c22b75916cce5e15af37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F11111049171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799359499', 'Capacete Moto Fechado GTN Fox Grafite/Cinza Viseira Cristal Inmetro Tamanhos 56 58 60 - FW3', '# Auto Equip # Seja bem-vindo(a)!!! --- Descrição: Capacete Moto Fechado GTN Fox Grafite - FW3 Com design esportivo e diferenciado, o capacete FW3 é perfeito para todos os motociclistas. Leve, estiloso e confortável, este moderno capacete vem com entrada e saída de ar, é fabricado em ABS super resistente e possui certificado de segurança. O melhor para você motociclista andar por aí com muita segurança, conforto e estilo! Capacetes da FW3 são projetados para lhe oferecer uma experiência inesquecível em cada um dos seus trajetos. Seus capacetes possuem uma estrutura compacta e se adapta perfeitamente ao condutor, preservando ao máximo sua segurança e garantindo trajetos confortáveis e divertidos. Características Técnicas: - Modelo GTN FOX; - Tamanho: 58 - Casco em ABS; - Viseira transparente de policarbonato 2,0 mm, podendo ser removida; - Forração em camurça Jet Black 6 mm (Removível); - Entrada e saída de ar; - Narigueira; - Reparo com trava de viseira; - Selo Inmetro; Conteúdo da Embalagem: - 01 Capacete Moto Fechado GTN Fox Grafite - FW3 Importante - Garantia de 03 meses; - Pedidos aprovados até 12h00 de segunda a sexta será enviada no mesmo dia; - Enviamos em até 24h úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - Imagens meramente ilustrativas; - A cor do produto pode variar de acordo com a tela do seu smartphone ou computador; - Utilize o campo de "Perguntas e respostas" e esclareça suas dúvidas com nosso suporte técnico.', 419.9, 419.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0u6p6keysv486', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600306931%2F18799359499', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697288075', 'Fluído Para Escova Trivitt 300ml Itallian Hairtech', 'O Fluído para Escova Trivitt 300ml é um produto desenvolvido para facilitar a escovação dos cabelos, ideal para quem busca proteção térmica e deseja evitar pontas duplas. Com uma fórmula que acelera a secagem dos fios ao usar o secador, ele forma um filme sobre os cabelos, proporcionando brilho intenso e maciez. Este fluído contém ativos importantes para o cuidado capilar: - Filtro Solar: absorve eficientemente a radiação UV-B, protegendo os fios dos danos solares e é resistente à água. - Queratina Vegeral: composta por 18 aminoácidos, penetra nas cutículas dos cabelos, restaurando as áreas danificadas e selando as cutículas para conservar a hidratação. - Óleo de Camelina Dourada: 100% vegetal, restaura a oleosidade natural dos fios, combate o toque áspero e melhora a elasticidade. - Emulsão de Silicone: oferece condicionamento superior, suaviza as cutículas e forma um filme protetor que previne e repara pontas duplas, além de facilitar a remoção sem acúmulo nos fios. Para usar, agite bem o produto e vaporize pequenas quantidades sobre os cabelos limpos e úmidos, mantendo a embalagem na posição vertical a uma distância de 20 cm. Em seguida, prossiga com a escovação utilizando o secador. Os benefícios do Fluído para Escova Trivitt incluem a proteção térmica, a restauração das partes danificadas do cabelo e a conservação da hidratação por mais tempo. Além disso, ele proporciona um sensorial agradável tanto em cabelos úmidos quanto secos, e diminui o tempo de secagem ao expulsar rapidamente a água dos fios. Cuidados: este produto é de uso externo e não deve ser utilizado em crianças. Mantenha-o fora do alcance de crianças.', 86.02, 74.84, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ll9n8kszksos20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969993035%2F20697288075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297292854', 'Água Oxigenda Oxidante Ox Itallian Color Volume 6 Volumes', 'A Emulsão Oxidante 06 Volumes Itallian Color é ideal para profissionais que buscam um produto eficaz para colorir e descolorir cabelos, garantindo proteção e cuidado aos fios. Desenvolvida para ser usada em conjunto com as colorações e pós descolorantes da linha Itallian Color, esta emulsão é perfeita para quem deseja resultados precisos e de alta qualidade. Com uma fórmula exclusiva que inclui os ativos Silk PPO, DENSFOR e K.TYON-R, a emulsão proporciona brilho acentuado e emoliência aos fios. A presença de lanolina, glicerina e vitamina E contribui para o condicionamento, hidratação e proteção dos fios durante o processo químico, além de oferecer um efeito calmante para o couro cabeludo. Para utilizar a Emulsão Oxidante Itallian Color, misture-a com a coloração ou o pó descolorante nas proporções indicadas nos respectivos modos de uso. Este produto é compatível com as linhas Itallian Color E Coloratto, além de ser indicado para o uso com o Descolorante Itallian e Premium. Entre os benefícios do uso desta emulsão estão a proteção dos fios durante a transformação química, a manutenção da cor e a facilidade de aplicação, graças à sua textura cremosa que evita escorrimento e garante uma distribuição uniforme. A fragrância agradável é um diferencial que torna o processo ainda mais confortável. É importante tomar alguns cuidados ao utilizar este produto: ele contém peróxido de hidrogênio e pode causar irritação na pele. Recomenda-se realizar a prova de toque antes do uso e evitar o contato com os olhos. Não é indicado para gestantes, crianças ou aplicação em cílios e sobrancelhas. Use luvas adequadas e armazene o produto em local seco e fresco, longe da luz direta, com a tampa bem fechada. A Emulsão Oxidante 06 Volumes Itallian Color é uma escolha confiável para profissionais que desejam oferecer um serviço de coloração e descoloração com segurança e resultados impressionantes.', 72.45, 63.04, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/br-11134207-820lj-mm7uxf4y89hj6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969993035%2F20297292854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793587220', 'Pastilhas De Freio Bosch S10 2.8 Diesel 4x2 2003 2004 2005', 'DESCRIÇÃO 1 - JOGO DE PASTILHA DIANTEIRA ( 4 Peças ) MARCA - BOSCH 0986BB0285 APLICAÇÃO GM GM S10 2.2 1996 A 2011 S10 2.4 1996 A 2011 S10 2.5 1996 A 2011 S10 2.8 1996 A 2011 S10 4.3 1996 A 2011 APLICAÇÃO SOMENTE PARA 4X2 - NÃO SERVE NA 4X4 Informações Importante: Recomendamos que os produtos sejam instalados por profissionais especializados; Trabalhando só com as melhores marcas do mercado. Sempre com Qualidade e Garantia. * Produtos Novo * Foto original do produto. * Compra 100% segura. * Enviamos para todo o Brasil. * Retirar todas as dúvidas no campo de perguntas. * Garantia. * Devolução Somente com a caixa e mercadoria em perfeito estado. * Para GARANTIA ou DEVOLUÇÕES o produto deve retornar ao vendedor com as caixas originais do produto sem estar danificadas, sujas ou rasgadas. ”Então guarde bem a embalagem com cuidado ate o termino do tempos de garantia” O produto em caso de garantia será enviado ao fabricante para analise de ate 30 dias.', 102.98, 102.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3xn4dqtobtne2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F540487527%2F23793587220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694500774', 'Tinta Premium Para Piso NovaCor Cinza Sherwin Williams 18L', 'SOBRE O PRODUTO Tinta à base de resina acrílica para pisos cimentados, mesmo que já tenham sido pintados anteriormente. Indicada para quadras poliesportivas, demarcação de garagens, pisos comerciais, áreas de recreação e etc. Com maior cobertura e resistência. Por isso, é muito resistente ao tráfego de pessoas, carros e intempéries, quando aplicada sobre superfícies corretamente preparadas e conservadas SOBRE A FABRICANTE A Sherwin-Williams é referência global em tintas, guiada por valores como integridade, qualidade e inovação. Com mais de 64.000 colaboradores, destaca-se pelo compromisso com pessoas, comunidades e sustentabilidade. Reconhecida por excelência em produtos e serviços, fortalece continuamente sua liderança no mercado.', 393.9, 393.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-824h4-mfl8wqjpkdu61a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F22694500774', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
