INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498419303', 'Compressor 1/2HP R404A Tecumseh AE2420Z-GS AE1334BR - 200V', 'Compressor 1/2HP R404A Tecumseh AE2420Z-GS AE1334BR - 200V O Compressor Tecumseh 1/2HP R404A AE2420Z-GS AE1334BR 200V é uma solução eficiente e confiável para sistemas de refrigeração que utilizam o gás R404A. Com 1/2HP de potência, esse compressor proporciona excelente performance no controle de temperatura, sendo ideal para câmaras frigoríficas, expositores refrigerados e sistemas de climatização. Sua alta capacidade de resfriamento e baixo consumo de energia fazem dele uma escolha inteligente para quem busca eficiência e economia. Desenvolvido com tecnologia avançada, o modelo AE2420Z-GS oferece um desempenho constante, garantindo uma operação silenciosa e de baixo custo. Sua robustez e design projetado para reduzir vibrações asseguram uma vida útil prolongada ao sistema de refrigeração, além de proporcionar maior confiabilidade nas instalações que dependem de um resfriamento eficiente. A compatibilidade com o gás refrigerante R404A torna o compressor ideal para ambientes que exigem resfriamento intenso. Além de sua eficiência energética, o Compressor Tecumseh AE2420Z-GS AE1334BR se destaca pela sua versatilidade em diferentes aplicações, atendendo com qualidade as necessidades de sistemas de refrigeração comercial e industrial. Se você procura uma opção que combine desempenho, economia e durabilidade, este compressor é a escolha ideal para otimizar seus processos de refrigeração e climatização.', 699.9, 699.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7reoz-m8xufpxl8yw214', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23498419303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201335960', 'Kit 02 Limpa Air Fryer Aerossol 250ml Super Dom', 'Limpa Air Fryer Aerossol 250ml Super Dom - 2un O Limpa Air Fryer Aerossol Super Dom é a solução prática e eficaz para manter sua air fryer sempre limpa e livre de resíduos de gordura. Sua fórmula de ação rápida facilita a remoção de sujeira e gordura acumulada, proporcionando mais praticidade e eficiência na manutenção do seu aparelho. O produto é fácil de aplicar, com um jato direcionado que alcança as partes de difícil acesso, como a cesta e a parte interna da air fryer. Você mantém sua air fryer sempre higienizada, preservando o sabor dos alimentos e evitando odores desagradáveis. Indicação de Uso: - Desenvolvido para remover rapidamente sujeiras, gorduras e odores, garantindo uma limpeza profunda sem danificar os componentes da sua Air Friyer. Embalagem: 02 frascos de 250ml', 43.22, 43.22, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhrlorlgcdmrc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F58201335960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
