INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22796613205', 'Meia HUPI Run Branco Preto - Tamanho Plus 42-46', 'Meia para Corrida e Ciclismo Tamanho Grande Conforto, design, tecnologia e qualidade são adjetivos que descrevem perfeitamente as meias HUPI. Testado e aprovado por atletas de diversas modalidades, a meia HUPI é um item indispensável para você. Praticar esportes com conforto e máximo desempenho é o seu objetivo, e também o nosso. Por isso a meia HUPI apresenta diversos destaques que fazem dela um item fundamental. O material utilizado na fabricação da meia é importado da Alemanha. Os fios de elastano e poliamida formam um conjunto cheio de vantagens. O principal destaque é o conforto, proporcionado pela transpiração que a meia oferece, deixando os pés secos e bem protegidos. A combinação da matéria prima assegura a flexibilidade oferecendo maior liberdade de movimento, sem que a peça laceie, perdendo sustentação. Na região dos dedos e calcanhar, os fios são dispostos em direções diferentes do restante da meia, fazendo com que a modelagem se torne muito mais anatômica, acompanhando o desenho dos pés. Esta característica também prolonga a durabilidade, impedindo o desgaste. COMPOSIÇÃO DO TECIDO: 97% Poliamida, 3% Elastano; Cano médio de 15 cm; Tamanho Plus: Veste do 42ao 46; CONTEÚDO DA EMBALAGEM: 1 Par de Meias HUPI; GARANTIA DO FORNECEDOR: Contra defeitos de Fabricação; FAIXA ETÁRIA: Adulto; Gênero: Unissex; Indicado para: Academia, Dia-a-dia, Corrida, Ciclismo.', 86.68, 86.68, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7qvd9-lkign4z83l2xc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F22796613205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
