INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43257655929', 'Kit com 18 Feltro Adesivo Cadeira Sofa Quadrado G 30MM SCOTCH 3M', 'A nova linha de Feltros Sintéticos Scotch traz mais qualidade e resistência para a proteção dos móveis da sua casa, evitando riscos. Os feltros possuem alta aderência, maior vida útil e qualidade 3M. NÃO RISCA - Protege e não danifica o piso RESISTENTE - Durável AMBIENTE - Interno TAMANHO - 3 cm x 3 cm CONTEÚDO - 9 feltros sintéticos quadrados O Feltro Sintético para Móveis Leves 3M Scotch ajuda você a proteger a beleza do seu piso. Equipados com adesivo poderoso e feltro durável, os protetores de piso aderem sem esforço aos pés dos seus móveis e fornecem proteção duradoura contra riscos e arranhões. Aplicações sugeridas Mesas Cadeiras Banquetas Pufes', 21.8, 21.8, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdy6-mbwcy9sv4x894a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F43257655929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
