INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251368498', 'Jogo de Cama Queen Gran Percalle 200 Fios Buddemeyer Manila 100% Algodão Estampado 4 peças', 'CARACTERÍSTICA DO PRODUTO: Delicados florais aquarelados em tons de lilás, aplicados ao fundo com textura de mosaicos, adornam a vira do sobrelençol e fronhas, criando uma composição refinada e muito charmosa. E os detalhes em ponto ajour enriquecem o acabamento com máxima sofisticação. Em Gran Percalle com 200 fios de puro algodão com fibras longas, o modelo possui toque extremamente macio e aconchegante, promovendo sensações agradáveis para uma cama perfeita. Qualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 sobrelençol 240x270cm + 1 lençol 160x200x40cm + 2 fronhas 50x70cm COMPOSIÇÃO: Tecido Gran Percalle 200 Fios - 100% algodão TIPO DE MATERIAL: Tecido 100% algodão DESCRIÇÃO: Jogo de Cama Queen Manila Buddemeyer - Com a beleza e o frescor de um exuberante jardim, a Coleção Manila Gran Percalle, convida a momentos acolhedores e muito relaxantes. Delicados florais aquarelados em tons de lilás, aplicados ao fundo com textura de mosaicos, adornam a vira do sobrelençol e fronhas, criando uma composição refinada e muito charmosa. E os detalhes em ponto ajour enriquecem o acabamento com máxima sofisticação. Em Gran Percalle com 200 fios de puro algodão com fibras longas, o modelo possui toque extremamente macio e aconchegante, promovendo sensações agradáveis para uma cama perfeita. Acompanha embalagem feita com o mesmo tecido do lençol, para manter os itens organizados e fáceis de guardar. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lave antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 60°C. O melhor sabão para manter as características do produto é o de coco ou neutro. Não colocar sabão diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Temperatura máxima da base do ferro 110°C. Não usar ferro a vapor. Não lavar a seco.', 652.07, 494.63, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-8224p-mhs3g45i7cap11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F58251368498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
