INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998323926', 'Tampão Bagagito Porta Malas Volkswagen Gol G2 G3 1996 a 2005 Carpete Preto R-Acoustic', 'Tampão Bagagito Porta Malas Volkswagen Gol G2 G3 1996 a 2005 Carpete Preto R-Acoustic Compatibilidade: Modelo: Volkswagen Gol G2 / GOL G3 Anos: 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005 Modelo do Fabricante: 1107 Especificações Técnicas: - Compatível com Gol 2 ou 4 portas; - Fabricado em MDF; - Revestido em Carpete Preto - Possui furos para Alto Falante 6x9 (os furos são cobertos pelo carpete, sendo opcional a utilização ou não); - Bordado o logo da montadora; - Encaixes perfeitos, e ótimo acabamento; - Acompanha um par de cordinhas; - Dimensões mm: 40X1063X475 mm - Peso: 4,700KG Descrição do Produto: Renove o visual do seu carro e garanta a segurança das suas bagagens com o nosso Tampão Bagagito de Alta Qualidade. Desenvolvido com medidas exatas para um encaixe perfeito, sem adaptações. Conteúdo da Embalagem: 01 Tampão 01 Par de Cordinhas Importante: 90 dias de garantia pelo fabricante Imagens e fotos meramente ilustrativas Recomendamos que a instalação seja realizada por um profissional especializado, e não nos responsabilizamos pelo mau uso do produto. Atenção: As compras realizadas em nome de Pessoa Jurídica estão sujeitas à cobrança de ICMS, conforme Protocolo ICMS 41, de 4 de Abril de 2008. Caso você tenha dúvidas sobre o percentual a ser aplicado, consulte a Cláusula Segunda, §1° do referido Protocolo.', 154.9, 147.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134207-820m7-mqrx4opjetj422', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F718208305%2F23998323926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
