INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993219152', 'Cilindro Roda Gm Corsa 1995 a 2003 - 846505 - CCR9283', 'Cilindro Roda Gm Corsa 1995 a 2003 846505 CCR9283 Pick-Up | 1.6 (8V) - Traseiro - Lado Direito - 7/8" / 22,22 mm - Sistema VargaO Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 46.59, 46.59, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd5n-m7ta0sm2kxjb9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22993219152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260906928', 'KIT ALBUM COPA DO MUNDO 2026 - CAPA DURA + 5 ENVELOPES', 'FIFA World Cup 2026™ As emoções do maior espetáculo esportivo do mundo eternizadas no maior álbum de figurinhas de todos os tempos! Uma coleção completa, com todas as seleções classificadas, cromos especiais e todos os detalhes para você acompanhar de pertinho a disputa pela taça da FIFA World Cup 2026™! O álbum tem 980 cromos, sendo 68 deles especiais, e contempla as 48 seleções que participam do Mundial de 2026, que acontece entre junho e julho no México, nos Estados Unidos e no Canadá. Este kit exclusivo inclui: Álbum Capa Dura 5 Envelopes de figurinhas (7 cromos por envelope)', 71.9, 71.9, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/sg-11134201-822wp-moehbn47qh357c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F58260906928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51909708942', 'Choker Pedrinha Transparente em Prata 925 Delicada e Minimalista', 'A Choker Pedrinha Transparente em Prata 925 é uma joia delicada e sofisticada, perfeita para quem ama elegância minimalista. A pedrinha transparente traz um ponto de luz sutil e refinado, valorizando o colo com leveza e brilho na medida certa. - Material: Prata 925 - Pedra: Zircônia transparente - Detalhe: Pedrinha central estilo ponto de luz - Comprimento: 35 cm + extensor de 5 cm - Fecho: Argola tradicional - Estilo: Minimalista e sofisticado - Acompanha: Certificado de garantia de autenticidade - Observação: Não acompanha caixinha Uma peça versátil e essencial, ideal para usar sozinha ou em mix de colares, trazendo um toque de brilho elegante para qualquer ocasião.', 144.0, 72.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-820l6-mnmudcbgnqx0d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F51909708942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24290962708', 'Suporte Smartphone Regulável Preto Antiderrapante KNUP OR-SP17', 'Suporte de Mesa OR-SP17 da KNUP é a solução perfeita para quem busca praticidade, estabilidade e conforto em seu espaço de trabalho. Com altura ajustável, ele oferece uma vista elevada de 900, garantindo um posicionamento ideal para suas tarefas. Sua estrutura é feita com uma placa de liga metálica, que proporciona resistência e durabilidade, e a almofada de silicone antiderrapante evita deslizamentos, oferecendo mais segurança e firmeza. Além disso, o suporte é dobrável, facilitando o armazenamento e a portabilidade. Fabricado com materiais de alta qualidade, como ABS, PC e liga de alumínio, ele alia resistência e leveza. Ideal para quem precisa de um suporte confiável para diversas atividades, como leitura, trabalho no computador ou outras funções que exijam um posicionamento adequado. ESPECIFICAÇÕES: - Modelo: OR-SP17 - Marca: KNUP - Altura ajustável - Vista elevada de 90º - Placa de liga metálica - Almofada de silicone antiderrapante - Dobrável para fácil armazenamento - Material: ABS + PC + Liga de alumínio CONTEÚDO: 1 Suporte de Mesa OR-SP17 Este suporte de mesa é perfeito para quem busca conforto, praticidade e organização em seu ambiente de trabalho ou estudo.', 23.36, 16.9, NULL, 'Mobile & Gadgets > Accessories > Phone Grips', 'https://cf.shopee.com.br/file/sg-11134201-7rbka-m5okr42104u8de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F24290962708', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397467601', 'Filtro Gasolina BRASILIA 1974/1981 - 43112 - FCC225', 'Filtro Gasolina BRASILIA 1974/1981 MOTOR 1600 ÁLC/GAS (GRANDE BICO 6/8mm) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 18.7, 18.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822zw-mo9r20p0dd6xa4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22397467601', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
