INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099029615', 'Kit 2 Desodorante Rexona Clinical Refresh 150ml', '• O Antitranspirante Rexona Clinical Refresh garante 96 horas de proteção contra suor e mau odor • Esse desodorante antitranspirante protege 3x mais contra a transpiração excessiva* e odor corporal que um antitranspirante comum • O Desodorante feminino Rexona é um aerossol de alta performance com secagem rápida que a protege todos os dias • A fórmula de Rexona Clinical garante máxima proteção e não deixa manchas nem marcas em suas roupas • Desodorante aerossol com uma textura leve e uma fragrância refrescante, fácil de aplicar, para que se sinta sempre seca e limpa • Este desodorante Clinical Refresh está disponível no formato aerossol A transpiração e o mau odor podem ser uma limitação na vida de muitas pessoas, o sentimento de desconforto toma conta nessas situações. Pensando nisso, Rexona desenvolveu o desodorante Antitranspirante Aerossol Rexona Clinical Refresh, que protege 3x mais contra a transpiração excessiva e odor corporal que um antitranspirante comum. Este antitranspirante possui ingredientes de alta performance que garantem 96 horas de proteção contra o suor, para se sentir sempre fresca, seca e limpa. Possui uma fórmula com textura leve e de secagem rápida, que não deixa manchas nem marcas em suas roupas. Para aplicar, agite bem antes de usar. Segure a lata a uma distância de 15 cm das suas axilas. Evite inalar diretamente. Aplique pequenas quantidades do produto em locais bem ventilados. Cada vez mais usamos materiais reutilizáveis em nossas embalagens, e facilitamos o descarte consciente da sua embalagem de desodorante para um planeta em movimento. É inofensivo para a camada do ozônio. A missão de Rexona é entender cada vez mais sobre a transpiração, e toda a linha de desodorantes antitranspirantes foi desenvolvida com tecnologia de ponta, para que você possa desafiar os seus limites diariamente. Disponível no formato desodorante feminino aerossol. Os produtos Rexona permitem você fazer mais, sem se preocupar com a transpiração. Rexona garante a melhor proteção contra a transpiração. Rexona Clinical, não te abandona! vs. um antitranspirante básico.', 35.38, 35.38, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-8259b-mqmd5ib19rf136', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21099029615', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19497124299', 'Kit 2 Desodorante Dove Clinical Original Clean Aerosol Antitranspirante 96h 150ml', 'Desodorante Antitranspirante Aerosol Dove Clinical Original Clean • O Desodorante Antitranspirante Dove Clinical Original Clean garante máxima eficácia contra transpiração • Este antitranspirante Dove garante proteção contra o suor excessivo e mau odor por até 96h, dando uma sensação de limpeza e frescor • Dove Clinical contém 1/4 de creme hidratante, para axilas ainda mais suaves, macias e com máxima proteção* contra o suor excessivo • Este desodorante aerosol é de rápida absorção e delicado para suas axilas • Além de proteger contra o suor e mau odor, este antitranspirante possui uma fragrância delicada Original Clean, a combinação perfeita de proteção, beleza e cuidado • Os desodorantes Dove são certificados como Cruelty-Free pela PETA, pois não realizam e nem realizarão testes em animais O Desodorante Antitranspirante Dove Clinical Original Clean cuida e protege as axilas por 96 horas contra suor e mau odor, mantendo as axilas secas o dia todo. Formulado com 1/4 de creme hidratante, este antitranspirante ajuda a manter a hidratação da pele das axilas, deixando-as suaves e macias. O desodorante Dove Original Clean oferece máxima proteção* contra o suor excessivo. Este desodorante aerosol, além de proteger contra suor e mau odor, possui uma fragrância delicada Original Clean, para uma sensação de limpeza e frescor. O desodorante Dove Original Clean é a combinação perfeita de proteção, beleza e cuidado. Dove proporciona proteção eficaz e cuidado para a pele das axilas, para que você possa se libertar de qualquer desconforto e se sentir confiante o dia todo. Para uma melhor proteção contra marcas de suor e irritação da pele siga estas dicas: após o banho, garanta que as axilas estejam bem secas; para obter o máximo do seu Desodorante Antitranspirante Aerosol Dove Clinical Original Clean agite a embalagem para ativar os ingredientes; segure-a voltada para cima a 15 cm das suas axilas e aplique um jato de dois segundos em cada uma. Dove é certificada Cruelty-Free pela PETA, sendo assim, não realizamos e nem realizaremos testes em animais em nenhum lugar do mundo. *Maior proteção contra transpiração oferecida por Dove.', 49.87, 49.87, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-8258v-mqm6qjoph5ot1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F19497124299', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
