INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22504999406', 'Filtro Ar Chevrolet Zafira 2.0 16v 2001 A 2005 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação ZAFIRA 2.0/ CD 2.0 16V MPFI 5P 2001 até 2004 ZAFIRA ELEGANCE 2.0 MPFI 16V 136CV 5P 2005 Conteúdo Da Embalagem 1 Filtro de Ar Tipo de Veículo para Carros Marca A Wega é uma empresa que pensa em primeiro lugar em seus clientes, tem como missão satisfazer plenamente as necessidades do mercado brasileiro, fornecendo peças automotivas de alta qualidade. A visão da Wega é ser uma empresa reconhecida no mercado, com base na ética e no crescimento sustentável e inovador. O Produto O filtro de ar é de extrema importância, por que ele elimina as impurezas que existem no ar do carro, para a mistura ar/combustível gerar uma combustão perfeita. Se o seu filtro estiver sujo e velho seu carro não passa na inspeção veicular, sem contar que se você rodar com o filtro de ar sujo seu consumo de combustível vai ser bem mais alto. Importante > Recomendamos que os produtos sejam instalados por profissionais especializados e não se responsabiliza pelo mal uso ou instalação indevida, causando a perda da garantia. Tempo de garantia: 3 Meses Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Imagem meramente ilustrativa Valor unitário EAN 7798001692746 Código do Fabricante FAP3268_WEG >', 32.25, 32.25, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbmr-lm8d81qzh8swef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22504999406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
