INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10597495517', 'Kit De Pintura Completo Atlas 3 | 4 | 5 | 6 | 7 Peças - Iniciante e profissional parede tinta pincel', 'Kit de Pintura Completo Atlas: Para Iniciantes e Profissionais Este kit abrangente oferece uma variedade de pincéis de alta qualidade, ideais para pintura de paredes. Disponível em conjuntos de 3 a 7 peças, o Kit Atlas é adequado para iniciantes e profissionais, garantindo durabilidade, facilidade de limpeza e versatilidade. Especificações Técnicas: Tamanhos: Disponível em conjuntos com pincéis de tamanhos variados, do número 3 ao número 7. Material: Cerda resistente que mantém a forma após o uso repetido. Multiuso: Ideal para pintura de paredes, bem como superfícies como madeira, gesso e metal. Fácil Limpeza: Pincéis de fácil limpeza para manutenção simples e rápida. Invista no seu talento criativo com o Kit de Pintura Completo Atlas e dê vida às suas ideias com confiança e estilo!', 43.55, 30.49, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvvt5a2us392fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F10597495517', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
