INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398888320', 'Kit 3 Vitamina C Targifor Cewin 1g com 10 comprimidos efervescentes', 'Cewin mudou e agora se chama Targifor Cewin: a mesma fórmula, em uma nova marca e com uma nova embalagem. Targifor Cewin é um suplemento alimentar de Vitamina C efervescente, indicado no fortalecimento da imunidade, com ação antioxidante e manutenção do metabolismo energético. Modo de uso: Contendo 1g de ácido ascórbico (vitamina C) em cada comprimido efervescente, é recomendada a dissolução de 1 comprimido em um copo de água (200ml). Targifor Cewin está disponível na versão de 10 comprimidos de vitamina C efervescentes e é indicado para adultos (pessoas com mais de 19 anos), gestantes e lactantes. TARGIFOR CEWIN® 1g NÃO CONTÉM GLUTEN.', 41.97, 41.97, NULL, 'Health > Medical Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-823o9-mojxru8px1qn87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23398888320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
