INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49410435441', 'Fones de Ouvido Lenovo LE302 – Fones de Ouvido Bluetooth 5.4 com Gancho Auricular Superelástico, Som HI-FI, Graves', 'Lenovo LE302 Baixa latência de alta definição Chip de jogo personalizado, 0,03 segundos de atraso imperceptível, melhor experiência de jogo personalizado. Mais estável e suave do que os fones de ouvido comuns. O Equipado com funções de toque populares, este auxílio auditivo com microfone oferece chamadas binaurais de alta definição, trocando músicas e chamadas de Siri. Bateria Super longa vida útil da bateria Super longa Um único fone de ouvido pode ser usado por cerca de 4 horas, e o compartimento do fone de ouvido pode carregar o fone de ouvido 3-4 vezes, com uma vida total da bateria de cerca de 30 horas e um tempo de espera de cerca de uma semana. Compatibilidade Forte O fone de ouvido pode ser usado com qualquer dispositivo que suporte Bluetooth, independentemente da marca e modelo do telefone móvel. Especificações do produto - - - - - -Especificações do produto - - - Nome do produto Lenovo LE302 Marca: Lenovo Modelo: LE302 Função de chamada Material do plástico: Plástico Material: Versão Bluetooth de 6,0 Classificação de cores da classificação: Preto, Branco, Roxo, Rosa, Verde Tipo de embalagem oficial: padrão oficial Classificação de fone de ouvido sem fio: verdadeiros fones de ouvido sem fio Desempenho à prova d''água à prova d''água à prova d''água: IPX5 Uso do clipe de ouvido: Tipo de clipe de ouvido Raio de transmissão: 15m Se orelha única ou dupla: estéreo de orelha dupla Método de conexão de cavidade de ouvido esquerdo e direito do fone de ouvido: conexão sem fio Desempenho à prova de poeira: Desempenho à prova de poeira: IP5X Método de conexão de fone de ouvido e dispositivo de reprodução com fone de ouvido: conexão Bluetooth. Descrição do produto - - - - - - - -Descrição do produto - - - - - - Chip Bluetooth 6.0, baixa latência de alta definição, 0,03 segundos de atraso imperceptível, chip Bluetooth 6.0, baixa latência de alta definição, 0,03 segundos de atraso imperceptível, aproveite o jogo, redução física de ruído. Captador de som preciso, chamadas de ouvido duplas, melhor qualidade de som. Adotando chips de jogo personalizados, 8-10 metros de conexão ininterrupta, forte anti-interferência e sinais mais concentrados no modo de jogo. --------O produto inclui------- 1 * um par de fones de ouvido 1 * caixa de carregamento 1 * Cabo de Carregamento 1 * manual do usuário (chinês/inglês) Dica: Dica: O envio é realizado por esse produto em estoque e será realizado em até 1 dia útil após o pagamento. Modo de usar: Depois de tirar os fones de ouvido do estojo de carregamento ao mesmo tempo, os fones de ouvido esquerdo e direito ligarão e emparelharão automaticamente (após os dois chips de fone de ouvido são emparelhados com sucesso: a luz do fone principal está ligada, O fone de ouvido secundário está desligado), depois ligue o telefone celular Bluetooth e clique para conectar ~ PS: A conexão Manual é necessária para o primeiro uso e, em seguida, os fones de ouvido podem ser conectados automaticamente após serem retirados: A conexão Manual é necessária para o primeiro uso e, em seguida, os fones de ouvido podem ser conectados automaticamente após serem retirados. OBSERVAÇÃO Devido às condições de iluminação, pode haver pequenas diferenças de cor entre a imagem e o produto real. Consulte o produto real para precisão.', 79.0, 57.38, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134201-823qa-mp7xbxsk55oua0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F49410435441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
