INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094360662', 'Sabonete em Barra Glicerinado Lux Botanicals Essências do Brasil Vitória-Régia 100g', 'Sabonete em Barra Lux Botanicals Essências do Brasil Vitória-Régia 100g O Sabonete Lux Botanicals Essências do Brasil Vitória-Régia traz uma fragrância inspirada na natureza brasileira, criada para revitalizar corpo, mente e alma. Sua fórmula glicerinada contém óleo de copaíba, que hidrata profundamente e ajuda a evitar o ressecamento da pele. Diferenciais: Fragrância cítrica e floral com óleo essencial de ylang. Sensação detox refrescante. Pele macia, suave e perfumada. Fórmula com glicerina e óleo de copaíba hidratante. Sustentabilidade: Embalagens 100% recicláveis e opção de refil com 70% menos plástico. Transforme seu banho em um momento único de autocuidado com a linha Essências do Brasil por Lux Botanicals.', 16.44, 16.44, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-824h3-me5stp0vvvggea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23094360662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
