INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256243335', 'Kit Freio Fazer 250 2005 2006 2007 2008 2009 2010 Cobreq', 'Cobreq, Tecnologia Mundial no seu Veículo Atingir e superar patamares de qualidade é a filosofia do grupo TMD Friction, que atualmente fornece equipamentos originais nas linhas leve, pesada e moto para as principais montadoras sediadas no Brasil e no mundo, exportando seus produtos para os quatro continentes. Possuímos certificações (ISO TS 16.949) que é o resultado da junção e aprimoramento de diversas normas internacionais, e representa hoje o que há de melhor em termos de Gestão da Qualidade, e também certificação (ISO 14.000) Certificação Ambiental. Linha Street As pastilhas e patins para freios COBREQ STREET são acessórios especificamente desenvolvidos para oferecer alta performance em frenagens e menor desgaste das pastilhas, patins, discos e tambores de freio. Seu coeficiente de atrito é indicado para scooters e motocicletas.', 75.9, 75.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261r-mlfaha15vdoo7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1410324431%2F58256243335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20216888812', 'Kit com 3 Cif Cremoso 450ml', 'O Kit contém: 3 CIF Cremoso Limpeza Milagrosa remove 100% da sujeira 450 ml cada. • Cif Cremoso Original é o produto de limpeza milagrosa que limpa fácil e dá brilho em mais de 100 superfícies*, removendo 100% da sujeira difícil, sem esforço • O Cif Cremoso Original possui um perfume suave, é mais concentrado e rende 7 garrafas do limpador comum • Fórmula com tecnologia poderosa que limpa sem riscar, removendo toda a sujeira desde a mais pesada até a limpeza de casa do dia a dia, deixando um brilho imbatível • Com o Cif, a limpeza nunca foi tão fácil e versátil. Cif Cremoso possui três variantes: Original, Limão e Laranja • Cif Cremoso Original é o produto de limpeza milagrosa para todo tipo de objeto como: eletrodomésticos, pias, couro sintético, borracha, plástico, porcelana e serve até como limpador de pisos • Cif promove uma limpeza milagrosa completa, com produtos versáteis que atendem a todas as suas necessidades. Cif. Sinta a limpeza acontecer!', 94.18, 73.73, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rdx2-mbwk6xnyzkm2f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F20216888812', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254783398', 'LEGGING FITNESS FEMININA CANELADA COM CÓS ALTO SEAMLESS+ DLK', 'Legging Fitness Feminina Canelada Com Cós Alto Seamless+ Liberdade de Movimentos e Conforto Descubra o máximo de conforto e estilo com a Legging Fitness Feminina Canelada Com Cós Alto. Confeccionada em tecido canelado de toque macio e maleável, ela é a escolha ideal para quem busca liberdade de movimentos durante as atividades físicas. A tecnologia Seamless, sem costura visível, elimina zonas de fricção, garantindo um ajuste perfeito e conforto incomparável. Combinando resistência e estilo, essa bermuda vai trazer uma sensação única de leveza enquanto você se move, sem restrições. Design e Funcionalidade O design canelado cria um visual sofisticado e moderno, enquanto o cós super alto duplo com textura canelada oferece sustentação extra ao abdômen. Essa bermuda é feita com alta Tecnologia Seamless - sem costura, que garante um toque macio, suave e alta respirabilidade, proporcionando extremo conforto e liberdade de movimentos para atividades como yoga, corrida ou treino na academia.', 194.99, 194.99, NULL, 'Women Clothes > Pants & Leggings > Leggings & Treggings', 'https://cf.shopee.com.br/file/sg-11134201-8261r-mke125bkopom5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F58254783398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
