INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798862154', 'Bolsa Infantil Menina Customize Cordão com Miçangas Tie Dye Pampili', 'Charmosa e cheia de estilo, essa mochila tem um toque especial em cada detalhe! Com acabamento levemente brilhoso em tons suaves, essa bolsa traz um visual delicado para os looks do dia a dia. O modelo acompanha um cordão com miçangas, que pode ser removido, para personalizar a bolsa, utilizar como pulseira, ou decorar onde preferir, deixando tudo ainda mais divertido e único. O modelo oferece alças ajustáveis e confortáveis, podendo ser utilizado como bolsa tiracolo ou mochila, além de alça superior para facilitar o manuseio. Um acessório prático, leve, que acompanha a menina com charme em todas as ocasiões.', 149.9, 149.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/br-11134207-820lc-mpwm14ylkdtt25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547100334%2F23798862154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
