INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099454192', 'Calça Feminina Pantalona em Plush Dianna Preto', 'Calça Feminina Pantalona Dianna, desenvolvida em Plush, que proporciona toque macio e confortável. Possui cós talhado largo com elástico franzido, garantindo melhor ajuste ao corpo. Conta com bolso quadrado sobreposto funcional, que agrega praticidade ao dia a dia. Sua modelagem pantalona oferece caimento soltinho e elegante, ideal para compor looks modernos com muito conforto.', 154.99, 154.99, NULL, 'Women Clothes > Pants & Leggings > Pants', 'https://cf.shopee.com.br/file/sg-11134201-82599-mr1r0to6fi814e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F22099454192', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
