INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199250183', 'MEDITAÇÕES O DIÁRIO DO IMPERADOR ESTÓICO MARCO AURÉLIO', 'MEDITAÇÕES O DIÁRIO DO IMPERADOR ESTÓICO MARCO AURÉLIO Poucas obras antigas foram tão influentes quanto as Meditações de Marco Aurélio, filósofo e imperador de Roma entre os anos 161 e 180. Uma série de textos e ensaios repletos de sabedoria, orientação prática e profunda compreensão do comportamento humano, continua sendo uma das maiores obras de desenvolvimento pessoal e espiritual, princípios éticos e de comportamento já escritas. As percepções e conselhos de Marco desde viver no mundo a lidar com a adversidade e interagir com os outros tornaram seus textos uma leitura obrigatória para estadistas, filósofos, líderes e estudiosos do comportamento humano. Para qualquer um que luta para conciliar as demandas da liderança com a preocupação com a integridade pessoal e o bem estar espiritual, as Meditações permanecem tão relevantes agora quanto eram há dois mil anos.Conhecido também como o imperador estoico, Meditações ainda traz consigo os fundamentos básicos do estoicismo. O estilo e a construção desta obra, originalmente um diário de anotações do imperador, torna possível redescobrir completamente os pensamentos de um dos líderes mais iluminados e inteligentes de qualquer época.. Informações Adicionais Autor: Aurélio, Marco Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: MEDITAÇÕES O DIÁRIO DO IMPERADOR ESTÓICO MARCO AURÉLIO Idioma: INDEFINIDO Páginas: 208 Edição: 1 ISBN-13: 9786587885339 ISBN-10: 6587885330', 49.4, 39.03, NULL, 'Books & Magazines > Books > Politics, Law & Social Sciences', 'https://cf.shopee.com.br/file/sg-11134201-7rd6m-luh6szqs7slqe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F21199250183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093076823', 'Relação Completa Cbx 250 Twister 2001 à 2008 Original Cofap', 'KIT RELAÇÃO COMPLETO CBX 250 TWISTER (COROA/PINHÃO E CORRENTE) - TMC410001. NOVO NA CAIXA - ORIGINAL COFAP PRINCIPAIS APLICAÇÕES: MOTOS: CBX 250 TWISTER ANO: 2001 Á 2008 *Aço 1045 *Corrente 520HX106L *37 dentes da coroa *13 dentes do pinhão Função da Coroa e do Pinhão: A Coroa e o Pinhão juntamente com a corrente são conhecidos como kit relação, e são fundamentais para uma pilotagem segura, sendo responsáveis por transmitir o movimento da saída da transmissão até a roda traseira. Como detectar problemas? Verifique se há desgastes nos dentes da coroa e do pinhão. Ao trocar verifique também: o ideal é realizar a troca do kit inteiro (coroa, pinhão e corrente) para garantir a durabilidade do conjunto, ruídos e folga na transmissão de força. ****Recomendamos que os produtos sejam instalados por profissionais especializados***', 122.49, 119.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rd4d-lvoq7ickqi2k0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369151526%2F22093076823', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698077406', 'Sandália Infantil Molekinha 2114274 Napa Turim', 'Sandália Infantil Molekinha Referência: 2114274 Descrição do Produto: A Sandália Infantil Molekinha Ref. 2114274 é perfeita para trazer estilo, conforto e segurança ao dia a dia das pequenas. Desenvolvida com materiais de alta qualidade, esta sandália une praticidade e durabilidade, sendo ideal para acompanhar as crianças em diversas ocasiões, como passeios, festas e momentos de lazer. Seu design moderno e delicado encanta e complementa qualquer look com charme e elegância. Benefícios: Estilo Versátil: Combina com diferentes tipos de roupas, desde vestidinhos leves até looks mais elaborados, ideal para diversas ocasiões. Conforto Prolongado: A palmilha anatômica e o forro macio garantem que as pequenas fiquem confortáveis o dia todo. Praticidade: Fácil de colocar e ajustar, permitindo maior independência para a criança e praticidade para os pais. Segurança: O fechamento em fivela ajustável e o solado antiderrapante proporcionam passos mais firmes e confiantes. Durabilidade: Material de alta qualidade que resiste ao uso constante, mantendo o visual bonito por mais tempo. Características Técnicas: Material: Sandália Infantil Feminina Referencia: 2114274 Material Externo (Cabedal): sintético Material Interno: Sintético bem-estar a cada passo. Solado: Borracha Antiderrapante Palmilha: Anatômica Altura do solado: 1 cm Indicação de Uso: Branco/Rosa/Amarelo e Napa/Turim/Rosa Tamanhos Disponíveis: 17 ao 25 Peso: 494 (varia conforme o tamanho) Fechamento: Fivela ajustável Solado: Produzido em borracha antiderrapante, oferecendo estabilidade e segurança em diferentes superfícies. Por que Escolher a Sandália Infantil Molekinha? A Sandália Infantil Molekinha Ref. 2114274 foi desenvolvida pensando no bem-estar e estilo das crianças. Seu design moderno aliado à funcionalidade faz dela uma excelente escolha para o dia a dia ou momentos especiais. É um calçado que oferece segurança, conforto e um toque especial de elegância para as pequenas. TABELA DE MEDIDAS: NUMERAÇÃO COMPRIMENTO DO PÉ (CM) 17 11,3 18 12,0 19 12,6 20 13,3 21 14,0 22 14,7 23 15,4 24 16,0 25 16,6 Garanta já a Sandália Infantil Molekinha Ref. 2114274 e proporcione à sua filha a combinação perfeita de conforto, segurança e charme. Este modelo é indispensável para quem busca qualidade e estilo em um único produto!', 69.99, 69.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7rfh5-m3nvqbe9o6p331', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1237041841%2F23698077406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
