INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297741432', 'Bancada Gourmet Americana Cinza Hp - Henn', 'Bancada Gourmet Americana Cinza Hp - Henn Bancada Gourmet Americana Cinza Hp Henn Apresentamos essa linda Bancada Gourmet da linha Americana desenvolvida pela Henn. Seu design moderno e funcional,. Ideal para transformar sua cozinha em um espaço sofisticado e prático. Produzida com materiais de altíssima qualidade garantindo segurança e durabilidade. Essa bancada é perfeita para tornar suas atividades culinárias mais prazerosas e eficientes. Preparar refeições vai se tornar uma experiência mais agradável! Garanta já a sua! Características Técnicas: - Produzido em MDP/MDF - Pintura na cor Cinza Hp - Acabamento em UV fosco - Design moderno Dimensões: Altura: 100,5 cm Largura: 145,5 cm Profundidade: 60,5 cm Informações importantes: *Não realizamos a montagem ou instalação do produto, porém acompanha manual de instruções. *Toda mercadoria segue segurada contra qualquer sinistro, em caso de anormalidade, recuse. *As caixas ou pacotes possuem identificação com o nome, cidade e quantidades de volumes relativos à compra para conferencia do recebedor.', 774.25, 774.25, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdxl-lzf7s9a6366ef9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23297741432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898676971', 'Kit Click Cadence Sanduicheira E Cafeteira Desperta 110V', 'Kit Click Cadence Sanduicheira E Cafeteira Desperta 110VEsse kit contém os seguintes itens: Sanduicheira Elétrica Cadence Click SAN400 Ela não é só uma sanduicheira! A Sanduicheira Click tem um design único e formato inovador. É uma companheira de bancada para fazer de tudo um pouco! Características: Botão Liga/Desliga com LEDs Indicadores: Não precisa tirar da tomada Pés Firmes: A sanduicheira não tomba Chapas Mais Profundas: Mais espaço, mais versatilidade Chapas Profundas e Antiaderentes: Superior estriada, inferior lisa Com a Click, preparar sanduíches deliciosos é só o começo! Dica de uso: Apenas antes do primeiro uso, unte levemente as chapas com um pouco de manteiga, óleo ou gordura. Feche o aparelho e aguarde esquentar (cerca de 5 min). Retire-o da tomada, espere esfriar e limpe. Pronto! Agora é só usar normalmente quando quiser. Certificações: Inmetro Código da Certificação: SGS Dimensões: 215 x 78 x 223 mm Garantia: 12 meses Cafeteira Elétrica Cadence Desperta Contrast CAF338 Tenha Café Fresquinho todos os dias. A Cafeteira Elétrica Desperta é perfeita para quem tem uma rotina atarefada e precisa de um cafezinho feito de forma simples e rápida. Fácil de limpar e compacta, é a sua melhor aliada da rotina! Destaques: Design que enaltece qualquer cozinha com seus detalhes e acabamentos Jarra de vidro: Fácil de lavar e não deixa resíduos nem odores Faz 18 cafés: Capacidade de 750 ml Base de aquecimento: Mantém o café aquecido após passar, sem queimar Potência: 600W (127V e 220V), eficiente para preparos mais rápidos Praticidade: Indicadores de medida de água na parte interna e de café na jarra Dica de uso: Para manter o café quente, recoloque a jarra na placa de aquecimento após servir, pois ela mantém a temperatura ideal enquanto a cafeteira estiver ligada. O café permanecerá quente até que a cafeteira seja desligada. Desligue a cafeteira quando a jarra estiver vazia ou quando não estiver sendo utilizada, retirando da tomada. Selo de Segurança: OCP SGS Dimensões: 193 x 255 x 149 mm Garantia: 12 meses', 229.9, 229.9, NULL, 'Home & Living > Decoration > Carpets & Rugs', 'https://cf.shopee.com.br/file/sg-11134201-7rdxs-mbpigjwx7t7re4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23898676971', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
