INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8470295130', 'Livro - Os meninos de Jo - Capa comum - Principis', 'Dez anos depois de publicar Rapazinhos: a vida em Plumfield com os meninos de Jo, a autora retoma a história dos dramas cotidiano se das façanhas dos meninos travessos mas descontraídos de Plumfield. O livro segue principalmente a vida de meninos apresentados no livro anterior, particularmente Tommy, Emil, Demi, Nat, Dane os filhos os filhos do professor Bhaer e Jo, Rob e Teddy, embora os outros também façam aparições frequentes, e Josie e Bess, duas primas de Demi e Daisy. Agora crescidos, eles precisam lidar com os dramas, as tempestades e as alegrias da vida adulta. Considerado o mais autobiográfico dos livros da série, Alcott tece com brilhantismo sua própria história, de maneira emocionante e com ligeiro tom de melancolia. Editora: Principis Edição: 1, 2021 Autor: Louisa May Alcott Idioma: Português Páginas: 352 Dimensões: L 15.50 x A 22.60 x E 1.90 ISBN: 9786555522211', 34.9, 34.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/0aa405308426f7fd870a887bc5254fca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8470295130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5292634259', 'Box com as obras revolucionárias George Orwell - Principis', 'George Orwell é um dos escritores mais importantes do século XX. Foi autor de romances, ensaios, críticas e artigos jornalísticos, com textos de fácil compreensão, inteligentes e críticos, apontando as injustiças sociais. Suas obras trazem oposição ao totalitarismo, o que as tornaram influentes na cultura popular, mas também na política. Conheça a essência de Orwell com o romance distópico 1984 e o romance satírico A revolução dos bichos._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2021_x000D_ Autor: George Orwell_x000D_ Idioma: Português_x000D_ Páginas: 640_x000D_ Dimensões: L 15.50 x A 22.60 x E 2.50_x000D_ ISBN: 7908312104955', 59.9, 39.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/1bd1f9f3028bacabb2568e6dd28532cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F5292634259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201033432', 'Válvula Termostática Para S10 2.5 Maxion Blazer 2.5 Maxion', 'IDEAL AUTO PARTS Desde 1990 IDEAL PARA SEU CARRO Valvula termostática MTE-THOMSON APLICAÇÃO CHEVROLET S10 2.5 De 2000 A 2001 Blazer 2.5 De 1997 A 2001 OBS: INÍCIO DE ABERTURA 72*C CODIGO DO FABRICANTE Mte Thomson 305.76 CONTEÚDO DA EMBALAGEM 01 Valvula termostática QUALIDADE Produto Novo GARANTIA 03 Meses De Garantia NOTA FISCAL Sim SUPORTE PÓS VENDA Sim SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER', 65.9, 65.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8227g-mhi371wyzjlx48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F58201033432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
