INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27193784066', 'Kit 3 Camisetas Dry Fit Masculina Manga Curta Uv Esporte Top', 'Apresentamos as Camisetas Manga Curta Dry Fit da marca Vida Loca, projetadas para atender às necessidades dos amantes de atividades físicas e ao ar livre. Com um tecido Dry Fit de alta qualidade, essas camisetas oferecem conforto e respirabilidade, permitindo que você se mova livremente durante suas atividades, seja na academia, caminhadas, corridas ou esportes variados. O design slim e a gola redonda garantem um caimento perfeito, enquanto a proteção UV proporciona segurança adicional durante a exposição ao sol. Essas camisetas são versáteis e se adaptam a diferentes estilos de vida. Disponíveis em um conjunto de três unidades, você terá opções para variar seu visual e estar sempre preparado para qualquer atividade. A combinação de funcionalidade e estilo faz dessas camisetas uma escolha inteligente para quem busca qualidade e desempenho em suas roupas esportivas. GUIA DE TAMANHOS Tamanho P | Altura: 71cm | Peito: 51cm | Tamanho M | Altura: 72cm | Peito: 53cm | Tamanho G | Altura: 73cm | Peito: 55cm | Tamanho GG | Altura: 75cm | Peito: 58cm | Invista em conforto, proteção e estilo com as Camisetas Térmicas.', 89.99, 89.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi3mhp7l4xkzd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443808233%2F27193784066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
