INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27488790086', 'Elden Ring: Become Lord 01', 'Guiado pela Graça, um Maculado chega às Terras Intermédias para iniciar uma longa jornada e reivindicar o trono do lendário Senhor Prístino. Pelo caminho, ele encontrará personagens intrigantes, enfrentará desafios em masmorras perigosas e batalhará contra poderosos inimigos. Uma adaptação vibrante e repleta de ação que transporta para as páginas toda a intensidade e grandiosidade do universo original de Elden Ring.Brindes: Marca páginas e adesivo', 58.26, 58.26, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rdwh-mcbarl3hd5br98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F27488790086', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
