INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897178146', 'Alarme Automotivo Fks Fk902 Fk 902 Universal + Desliga Rádio', 'O alarme FKS FK902SB Plus tem muita qualidade, diversas funcionalidades e ainda oferece um custo-benefício excelente. Mesmo sendo recheado de funções, ele é super prático de usar, e tudo isso para evitar com máxima eficiência qualquer tentativa de furto do seu automóvel. Para isso, ele conta com recursos para travar e destravar as portas, subir vidro elétrico, rearme automático, sensores de ultrassom e muito mais. Informações Técnicas: • Função desliga rádio integrada com saída positiva. • Tamanho compacto. • Comando de travas negativo. • Travamento automático de portas após a ignição ser ligada. • Auxiliar 1 - Sobe vidro inclusive das marcas FIAT e VW com vidros automatizados, subida e descida original de fábrica. • Auxiliar 2 - Desce vidro ou abre o porta-malas. Sensor de ultrassom com ajuste de sensibilidade. • Funções programáveis: seleção de tempo de travamento, seleção do tom da sirene, arme automático, rearme automático, cancelamento de ultrassom. • Outras funções: pânico, localizador e check control. • Sirene dedicada. Obs.: Não tem a função de bloqueio. Itens inclusos: • 1 Módulo Central • 1 Sirene • 2 Controles remotos (modelo CR941 Preto) 1 Tecla de programação • 2 Cápsulas de ultrassom • 1 Manual de instruções • 1 Certificado de Garantia • 1 Chicote e Fios', 218.0, 199.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Alarms and Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpf7dvnu7cd175', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F23897178146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15192313463', 'Pedestal tripe suporte Ask Para Caixa De Som Acústica Cxm Preto', 'Desenvolvido para ser robusto, o tripé para caixa de som CXM é fabricado com o que há de melhor em matéria prima! Compatível com qualquer modelo de caixa, o suporte é universal com capacidade de carga de 60 kg, e pode chegar a uma altura de 1,5 metros. Para segurança, além do tripé possuir uma trava de metal para evitar que o mesmo se feche, ele também possui uma arruela de aço soldado em sua ponta, para que a caixa de som fique apoiada por inteira. *Não acompanha chápeu Dados Técnicos: Peso (kg): 2,10 Capacidade de carga (kg): 60 Altura Máx. (cm): 1,50 Altura Min. (cm): 1,30 Diametro do Tripé (cm): 70 - 80 Material: Aço / Plástico Ajuste: Altura Características Especiais: Material de alta resistência com grande capacidade de carga. Características principais Marca ASK Modelo cxm Unidades por embalagem 1 Outras características Material: Aço/Plástico Lugar de colocação: De pé Peso máximo suportado: 60 kg É ajustável: Sim Altura: 1.5 " Peso: 2.1 g É kit: Não', 193.0, 134.99, NULL, 'Audio > Others', 'https://cf.shopee.com.br/file/4402c396d07e1a59f3b311e7db9fbe2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F15192313463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
