INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799207615', 'Kit 10 Flanela Microfibra Limpa Vidro Pia Pano Multiuso', '"Apresentamos o revolucionário Pano de Microfibra Multiuso, confeccionado com tecido de primeira qualidade, composto inteiramente por 100% de microfibra. Este incrível pano é a solução definitiva para suas tarefas de limpeza. Sua composição de microfibra garante a máxima absorção, enquanto sua incrível tecnologia de fabricação impede que solte fiapos ou pelinhos, proporcionando uma limpeza impecável. Sua facilidade de torção e manuseio torna a limpeza uma tarefa simples e eficiente. Este pano versátil é a escolha ideal para qualquer tipo de limpeza, desde a sua casa até a manutenção de seu veículo. Deixe o Pano de Microfibra Multiuso elevar o padrão da sua limpeza, proporcionando resultados excepcionais a cada uso. Contém: 10 unidades Cor: Colorido Cores Sortidas Medidas: 30 largura x 30 altura cm Composição: 80% poliéster e 20% poliamida LAVAGEM: Nossos panos de microfibra são de excelente qualidade, excelente textura e muito funcional"', 49.99, 25.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lshr5u2s8fuj7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388739239%2F19799207615', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209836885', 'Vestido Regata Infantil Feminino Lilica Ripilica', 'O vestido Lilica Ripilica Alto Verão é delicado e versátil, perfeito para os dias de calor. Confeccionado em malha trabalhada, proporciona conforto e um caimento leve. O destaque especial está na prega frontal, que adiciona um detalhe charmoso e moderno à modelagem. Para completar, a peça conta com uma estampa localizada da Lilica Ripilica, trazendo autenticidade e um toque exclusivo ao visual. Ocasião de Uso Ideal para momentos de lazer, passeios em família ou encontros casuais, é uma peça prática e cheia de estilo. Pode ser combinada com sandálias, sapatilhas ou tênis, criando looks fresquinhos e encantadores para o verão.', 249.0, 174.3, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-820nx-mnmzkewy8rno79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58209836885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258080617', 'Conector Derivação De Fios Até 1,5 Mm Vermelho', 'Vantagens de comprar com a Puma Auto Parts: • Compra 100% segura • Compras efetuadas até as 12H são enviadas no mesmo dia. (Considerando dias úteis) • Produto de qualidade e com nota fiscal • Diversas formas de pagamento • Dúvidas no chat 10 Conectores de Derivação • Disponível na Cor: Vermelho • Fio 0,50 a 1,50mm Obs: O conector de derivação é dotado de uma lâmina que remove a capa isolante dos fios. Os fios se conectam através da própria lâmina e são isolados através isolados através do corpo de polietileno com aditivação anti-chama. A remoção da capa isolante pelo próprio conector que reduz o tempo de aplicação, aumentando a produtividade dos instaladores. Conteúdo da Embalagem: • 10 Conectores de Derivação Vermelho Cabo 0.50 a 1.50mm Importante: Garantia de 15 Dias Valor Unitário Imagens Reais do Produto', 10.81, 10.81, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-820lw-mnolkwdx5jpe33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401365662%2F58258080617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40200360688', 'Livro Colorindo | Carros | 12 Gizes de Cera', 'Livro Colorindo | Carros | 12 Gizes de Cera 30 Desenhos Para Colorir | 12 Gizes de Cera O Kit Colorindo Carros é a escolha ideal para estimular a criatividade, proporcionando diversão e relaxamento. Com 30 páginas exclusivas de ilustrações envolventes e 12 lápis de cera vibrantes , o kit é perfeito para todas as idades, ajudando no desenvolvimento de habilidades motoras e artísticas. Além de ser uma ótima opção para lazer, também serve como atividade terapêutica e educativa. Seguro e recomendado para crianças e adultos, é a combinação perfeita para dar vida à imaginação! Destaques: 30 páginas com ilustrações encantadoras. 12 lápis de cera vibrantes e de fácil aplicação. Desenvolve habilidades motoras e criatividade. Ideal para lazer, terapia e educação. Seguro e recomendado para todas as idades. Especificações do livro Colorindo | Carros | 12 Gizes de Cera: Título: Colorindo | Carros | 12 Gizes de Cera Subtítulo: 30 Desenhos Para Colorir | 12 Gizes de Cera Ano de Edição: 2024 Capa: Cartonado Acabamento: Laminação Brilho Miolo: Offset Páginas: 30 Dimensões: 32 x 1 x 24 cm Peso: 0,341 kg ISBN 9788557581920 Editora: Magic Kids', 18.38, 18.38, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9jbwuc0iwxl68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F40200360688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
