INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12107637181', 'Pandeiro 10" Polegadas Pele Preta Luen Abs Profissional', 'Pandeiro 10" Polegadas Pele Preta Luen Abs Profissional O Pandeiro de 10 polegadas profissional Luen com pele leitosa é o produto mais vendido em todo o território nacional, isso devido à utilidade que este instrumento tem na execução de diversos ritmos que não estão ligados diretamente ao Samba, como: Jazz, Funk, Soul , MPB, Blues dentre outros. O Samba é realmente o ritmo mais tocado com este pandeiro, porém não se limita somente à ele. Especificações Tamanho: 10" Polegadas Pele: Nylon (Preta) Ferragens: Inox Material: Abs (Plástico) Platinelas: Latão Altura: 6 cm Largura: 30 cm Comprimento: 30 cm Peso: 506 g Contém: 01 Pandeiro 01 Chave de afinação *Imagens Meramente Ilustrativas!', 113.5, 113.5, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Percussion Instruments', 'https://cf.shopee.com.br/file/de5b1276ad722bc30d11591fb8bb4d2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F12107637181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17771090105', 'Bíblia De Estudo | NVT | Preta', 'Bíblia De Estudo - Mundo Cristão Na Caixa A mais completa e abrangente O que é A bíblia de estudo NVT reúne o texto bíblico da nova versão transformadora tradução publicada em 2016 pela editora Mundo Cristão e uma série de recursos adicionais que visam auxiliar o leitor no entendimento das escrituras sagradas. A quem se destina À semelhança da edição comum da NVT esta bíblia de estudo procura oferecer as verdades mais densas da fé cristã de modo claro e acessível. Assim sendo todo leitor potencial da NVT é um leitor potencial também da bíblia de estudo NVT. Diferenciais A bíblia de estudo mais completa disponível em língua portuguesa. Contextualizações em diversas áreas do saber linguagem clara e acessível. Conteúdo atualizado com os mais recentes debates acadêmicos. O que contém Introduções aos livros da bíblia cronologias referências cruzadas notas temáticas estudo de termos originais mapas plano de leitura índice de assuntos dicionário concordância e muito mais.', 260.66, 260.66, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/428eb87178b71bbf8b6d31dc45ae2fd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F17771090105', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9389131193', 'Strap Lock Trava Correia Talabarte Par 2 Peças Guitarra Violão Contra Baixo Dourado + Palhetas', 'Se você já perdeu seu momento de solo na musica, quando a correia escapou e tomou um baita de um susto, ou pior sua guitarra caiu e quebrou? Sabe como é importante ter segurança no seu equipamento. Com Strap Lock você tem segurança e facilidade ao tirar e colocar sua correia. Através do sistema de porcas e ruelas você ficara a vontade para tirar a mão do instrumento sabendo que ele não vai cair. Além de prolongar a vida útil da sua correia, por conta do sistema de com o pino fixo. Esta esperando o que? Compre e seja feliz. Descrição: Roldana com Trava Strap LockDourado Produto de boa qualidade Segura com precisão a correia ( trava por um sistema de porcas e arruela) Contém: 1 Par de Roldana 2 Palhetas Sortidas *Imagens Ilustrativas', 48.47, 48.47, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/927beeff142a2aa6f53f9f0e45611e5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F9389131193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
