INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54414656680', 'Lakerain Base em Cushion Vermelha, À Prova d’Água, Longa Duração, Toque Leve e Cobertura Perfeita', 'Destaques principais: ✔️ 72 horas de duração: à prova d’água, resistente ao suor e resistente à transferência para cobertura perfeita por até 72 horas. ✔️ Proteção da pele: fórmula enriquecida com FPS, com hibisco e própolis vermelha para maior elasticidade. ✔️ Fórmula fresca: lacre de alumínio mantém a frescura e evita a descoloração. ✔️ Precisão profissional: puff em formato de ovo garante acabamento uniforme em áreas de difícil alcance. ✔️ Brilho ajustável: textura leve e respirável para um brilho natural, sem aparência pesada. Dica de aplicação: aplique uma pequena quantidade no puff e dê batidinhas delicadas para cobertura uniforme.', 38.0, 37.5, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134253-8258n-mqxwmgqtrjev38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F54414656680', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594545112', 'Climatizador De Ar Industrial Ventisol Pro 60 Litros 150W Ventilador Umidificador Galpão Casa Sala', 'Climatizador De Ar 60 Litros 150w Clin60 Pro Ventisol O Climatizador Ventisol PRO 60 Litros é a solução perfeita para quem busca refrescar e umidificar o ambiente com eficiência e economia. Além de proporcionar maior conforto térmico, seu sistema ajuda a minimizar problemas respiratórios e desconfortos causados pelo ar seco, já que sua função de climatização umidifica o ar, podendo ser potencializada com o uso de gelo. Com potência de apenas 150W, o Ventisol PRO é econômico e ideal para uso residencial ou comercial, cobrindo grandes áreas com eficiência. Seu design moderno, painel de fácil operação e rodízios que facilitam o transporte garantem praticidade no dia a dia. O sistema evaporativo tipo Colmeia resfria o ar de maneira natural, mantendo o ambiente agradável mesmo nos dias mais quentes. Características: > Econômico: baixo consumo de apenas 150W; > Grande capacidade: reservatório de 60 litros; > Sistema tipo Colmeia: resfria e umidifica o ar; > Oscilação vertical automática e horizontal manual para melhor distribuição do ar; > 3 velocidades de ventilação ajustáveis; > Proteção inteligente da bomba: desliga automaticamente em caso de falta de água no reservatório; > Portátil: 4 rodas resistentes para facilitar o transporte entre ambientes; > Ideal para residências e comércios de médio a grande porte. Especificações: > Modelo: Linha PRO > Capacidade do reservatório: 60 litros > Potência: 150W > Tensão: 220V (não é bivolt) > Velocidades: 3 opções > Oscilação: vertical automática / horizontal manual > Sistema de climatização: evaporativo tipo colmeia > Peso líquido: 12 kg > Cor: Branco/Cinza - Marca: Ventisol - Garantia: 12 meses contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 1428.7, 1428.7, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-82580-mg48bce8rfns42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F23594545112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41156437608', 'Kit Copos Lilo & Stitch 280 ml Ohana - Plasútil', '- ATENÇÃO - Esse anúncio corresponde ao envio de uma unidade. Esse copo possui 8 decorações diferentes (como mostra a foto principal). Não é possível escolher a arte. O envio é feito de forma aleatória. - Os copos de 280 ml são decorados com os personagens preferidos da criançada e com isso, são ótimos aliados na hora da hidratação nas refeições. - Ótima opção para lembrancinha de aniversário ou festas temáticas. - Fabricado em plástico polipropileno (PP). Atóxico e livre de bisfenol-A (BPA FREE). - Pode ser levado ao micro-ondas e freezer. - Decoração injetada no plástico, não adesivada: segurança aos pequenos. Dimensões (Diâmetro x Alt): 7,8 x 10,3 cm Volume : 280,0 ml', 24.99, 24.99, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbo1i646t86f3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F41156437608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
