INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47302500435', 'Lovito Vestido Vermelho Sem Mangas com Babado na Barra Moda Modesta DRB632BRL662BD', '----------- ✅DESTAQUES -❤️Fresco e Confortável ✅DESCRIÇÕES Estampa: Lisa Estilo: Casual Tamanho Plus: Não Composição: 96% Poliéster 4% Elastano Tipo de Caimento: Regular Transparência: Não Elasticidade: Pouca Elasticidade Região de Origem: Brasil ✅O PACOTE INCLUI 1X Vestido ✅APRESENTAÇÃO LOVITO Lovito é uma marca emergente que acredita no poder feminino, comprometida em oferecer opções de roupas fashion e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança. ✅NOTAS DE COMPRA Compare suas medidas com nossa tabela disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, entre em contato conosco e responderemos o mais rápido possível.😊', 66.9, 30.9, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi0mu2246gap58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632995122%2F47302500435', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
