INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14996815304', 'Aro De Roda Dianteiro Aço Honda Biz 100 110i 125 Mega Solda', 'O Aro Dianteiro mega solda Pro Tork é fabricado em aço reforçado, com emendas perfeitas através da tecnologia da mega solda. Possui pintura automatizada que garante a durabilidade do produto em qualquer ambiente. Especificações: - Fabricado em Aço; - Chapa altamente resistente; - Cor: Preto, Cromado; - Modelo: Dianteiro; - Tamanho: 17 x 120; - Marca: Pro Tork. Aplicação: - Biz 100 1998; - Biz 100 1999; - Biz 100 2000; - Biz 100 2001; - Biz 100 2002; - Biz 100 2003; - Biz 100 2004; - Biz 100 2005. - Biz 125 2006; - Biz 125 2007; - Biz 125 2008; - Biz 125 2009; - Biz 125 2010; - Biz 125 2011; - Biz 125 2012; - Biz 125 2013; - Biz 125 2014; - Biz 125 2015. - Biz 110i 2016; - Biz 110i 2017; - Biz 110i 2018; - Biz 110i 2019. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada.', 115.69, 87.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lk8fr0imuqlt91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F14996815304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23320293840', 'Tampa Lateral Inferior Pro Tork Modelo Original Moto Titan 150 Mix 2009 2010 2011 2012 2013 Preto', 'A Tampa Lateral Inferior Pro Tork Titan 150 Mix 2009 - 2013 é produzida nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricadas em ABS 100% virgem, são extremamente resistentes aos raios UV, tornando-se assim o melhor custo-benefício do mercado. Características: - Modelo: Original; - Cor disponível: Preto; - Tonalidade de cores semelhante ao original; - Marca: Pro Tork. Aplicação: - Titan 150 Mix 2009; - Titan 150 Mix 2010; - Titan 150 Mix 2011; - Titan 150 Mix 2012; - Titan 150 Mix 2013. Atenção! Devido ao desgaste da pintura da motocicleta com o passar do tempo, pode haver uma pequena divergência na tonalidade das cores. Instalação: - A instalação deve ser feita por um profissional especializado. A Sportbay não se responsabiliza por instalação mal realizada.', 96.63, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-23010-ekid52bkwtmv87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23320293840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22620301616', 'Espelho Retrovisor Articulado Pro Tork Original Biz 125 / Bros 150 2009/14 (Par)', 'Apresentamos a você os retrovisores PRO TORK Modelo Original Articulado, a solução ideal para melhorar a segurança e a visibilidade durante suas viagens de moto. Com esses retrovisores de alta qualidade, você terá uma visão clara e ampla do tráfego ao seu redor, mantendo-se sempre ciente do que está acontecendo nas ruas e estradas. Marca: PRO TORK Lado: DIREITO e ESQUERDO. Especificações e Benefícios: - Nossos retrovisores são projetados com atenção aos detalhes, combinando funcionalidade e estilo em um só produto. Eles são fabricados com materiais duráveis e resistentes, garantindo sua longevidade e capacidade de suportar as condições variadas do ambiente. - Além da sua funcionalidade essencial, esses retrovisores também oferecem um design moderno e elegante que complementa a aparência da sua motocicleta. - Ao investir em nossos retrovisores de motocicletas, você estará priorizando sua segurança e a dos outros usuários da estrada. Com uma visão clara e ampla dos veículos ao seu redor, você poderá tomar decisões mais informadas e evitar possíveis acidentes. Não deixe de adquirir os retrovisores de motocicletas PRO TORK de qualidade superior para aprimorar sua experiência de pilotagem. Melhore a visibilidade, a segurança e o estilo da sua moto hoje mesmo! Aplicação: - BIZ 125 2006 à 2017; - POP 100 2007 à 2014; - POP 110 2015 à 2017. Atenção: Recomendamos que a montagem seja realizada por um profissional especializado. A Loja não se responsabiliza por montagens errôneas ou mal uso do produto.', 84.11, 45.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Side Mirrors', 'https://cf.shopee.com.br/file/sg-11134201-23010-e8tyqx7lvtmvb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22620301616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
