INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694681646', 'CD Imagine Dragons - Night Visions (Deluxe) - Importado', 'CD Imagine Dragons - Night Visions (CD Deluxe Version) - Importado Lançado no dia 04 de setembro de 2012, Night Visions é o álbum de estúdio de estréia da banda norte-americana de rock alternativo Imagine Dragons, a maior banda revelação de 2013. Imagine Dragons é uma banda americana formada por quatro músicos de Las Vegas que com estilo rock alternativo e essência indie conquistaram milhares de fãs pelo mundo. O álbum estreou na 2ª posição na Billboard 200. Confira agora a versão deluxe do álbum Night Visions! It''s Time é o primeiro single do álbum. A música está entre as mais pedidas das rádios nos Estados Unidos e Europa e ganhou recentemente um cover no seriado musical Glee. Enquanto isso, a música Radioactive foi tema do filme A hospedeira e hoje é uma das músicas mais tocadas mundialmente. Repertório do CD: 1. Radioactive 2. Tiptoe 3. It''s Time 4. Demons 5. On Top Of The World 6. Amsterdam 7. Hear Me 8. Every Night 9. Bleeding Out 10. Underdog 11. Nothing Left To Say / Rocks 12. Cha-Ching (Till We Grow Older) 13. Working Man 14. My Fault 15. Round And Round 16. The River 17. America 18. Selene 19. Cover Up 20. I Don''t Mind', 89.9, 67.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-825zz-mm0gj2864kqs42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F23694681646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
