INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297076250', 'Namorada de Aluguel Vol. 8', 'Após ser promovido de cliente para vizinho, Kazuya se aproxima mais um pouco de Mizuhara. Mas esse breve momento de felicidade é escurecido pela sombra de Mami! Além disso, Mizuhara acaba com uma impressão errada por causa de uma artimanha de Ruka...? Os dias agradáveis se transformam em provações! Sentimentos e laços serão testados agora, no volume 8!', 24.86, 24.86, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rbm4-ln3rrj6rv8w60b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22297076250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
