INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499379480', 'Câmera De Vigilância IP66 3MP 180 Wifi Ipega KP-CA207', 'A câmera de segurança KP-CA207 oferece proteção abrangente com visão noturna colorida, detecção de movimento e controle via app Carecam Pro. Com ângulo de 180°, ela captura todos os detalhes, enquanto o áudio bidirecional permite comunicação instantânea. Resistente e eficiente, com proteção IP66, é a escolha ideal para monitoramento interno e externo, garantindo segurança 24 horas por dia. ESPECIFICAÇÕES: - Marca: Ipega. - Modelo: KP-CA207. - Aplicativo compatível: Carecam Pro. - Voltagem: 110-240V / 50-60Hz. - Saída: DC12V - 2.0A. - Sistema Operacional (PC): LINUX. - Sistema Operacional (APP): Android / iOS. - Sensor de Imagem: 1/2.8’’ de alta sensibilidade. - Codificação de Imagem: H.265 para eficiência de armazenamento. - Resolução de Imagem: 2304x1296 (3MP). - Qualidade de Gravação: 2304x1296p. - Detecção de Movimento. - Lente de2.3mm com ângulo de visão ultra amplo de 180° Graus. - Iluminação de 6 LEDs infravermelhos para visão noturna avançada. - Tecnologia IR-CUT para imagens claras em qualquer iluminação. - Armazenamento com suporte para cartão de até 128GB. - Visão Noturna Colorida para uma visualização aprimorada no escuro. - Conectividade: Wifi integrado para controle remoto. - Proteção: IP66 resistente a intempéries, ideal para uso externo. - Função Panorâmica com cobertura total do ambiente. - Áudio Bidirecional para comunicação em tempo real com quem está no local. - Tela Dupla para monitoramento simultâneo. CONTEÚDO: 1x Câmera de Segurança KP-CA207 1x Kit de fixação completo 1x Fonte de Alimentação 1x Manual de Instruções detalhado', 195.0, 191.1, NULL, 'Cameras & Drones > Security Cameras & Systems > CCTV Security Cameras', 'https://cf.shopee.com.br/file/sg-11134201-7rblt-m5soe1gzv7dj47', 