INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393856143', 'Mouse Gamer 6 Botões 12.800 DPI Sensor Instantâneo Knup KP-MU026', 'Mouse Óptico Gamer 6 Botões Knup KP-MU026 é a escolha perfeita para quem busca desempenho e precisão em jogos. Com um sensor instantâneo A825F e uma incrível resolução de até 12.800 DPI, este mouse oferece resposta rápida e movimentos precisos, essenciais para jogadores que exigem alto desempenho. Além disso, a durabilidade é garantida com botões que suportam até 5 milhões de cliques, oferecendo longa vida útil para intensas sessões de jogo. Seu design ergonômico e as dimensões ideais (120x61x39mm) proporcionam conforto e facilidade de manuseio, mesmo durante maratonas de jogos. ESPECIFICAÇÕES: - Modelo: KP-MU026 - Tipo: Mouse Óptico Gamer - Quantidade de Botões: 6 - Sensor: A825F Instantâneo - Resolução: 800/1.600/3.200/4.800/6.400/12.800 DPI - Vida Útil dos Botões: 5 milhões de cliques - Dimensões: 120x61x39mm (CxLxA) CONTEÚDO: 1 Mouse Óptico Gamer Knup KP-MU026', 119.54, 75.0, NULL, 'Computers & Accessories > Keyboards & Mice > Mice', 'https://cf.shopee.com.br/file/sg-11134201-7rd6x-m7tqn8xf34agb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F22393856143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
