INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297735579', 'Buzina Original Gauss Renault Clio', 'Buzina Gauss Renault Clio: A Segurança Sonora que Você Precisa! Dirigir com segurança é fundamental, e ser ouvido no trânsito é parte essencial disso. Uma buzina eficiente garante que você alerte outros motoristas e pedestres em situações de risco, prevenindo acidentes e protegendo você e sua família. Por que uma Buzina Nova Faz Toda a Diferença? Com o tempo, a buzina do seu carro pode perder a potência ou até mesmo parar de funcionar. Uma buzina em perfeito estado garante que você seja notado em momentos cruciais. Por Que Escolher a Buzina Gauss? A Gauss é uma marca reconhecida pela qualidade e durabilidade de seus produtos automotivos. Ao escolher a buzina Gauss para o seu Renault Clio, você garante um produto confiável, com alta performance e longa vida útil. Compatibilidade Perfeita para o Seu Renault! Esta buzina é compatível com os seguintes veículos Renault: Clio (motores D7D, K4M, D4D): 1996 a 2016 (verifique os anos e motores específicos na lista completa) Kangoo (motores K7M, D7D, K4M, D4D): 1999 a 2025 (verifique os anos e motores específicos na lista completa) Especificações Técnicas que Fazem a Diferença: Voltagem: 12V Forma: Caracol Outras Marcas Equivalentes: DPL: DPL101040 VETOR: VT216 Não deixe a segurança para depois! Garanta já a sua Buzina Gauss e dirija com tranquilidade e confiança. Clique agora e adicione este item essencial ao seu carrinho!', 59.99, 59.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kt3jy6vn2d01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F19297735579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
