INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206085832', 'Pneu Michelin F 800 GS Adventure Tiger 800 XR XJ 900 S 150/70-17 Anakee 3', 'Pneu Michelin Anakee 3 150/70-17 Experimente o desempenho excepcional do Pneu Michelin Anakee 3, projetado para enfrentar terrenos mistos com facilidade. Com uma relação de aspecto de 70, este pneu oferece excelente aderência em superfícies secas e molhadas, garantindo segurança em todas as condições climáticas. Sua durabilidade prolongada proporciona uma vida útil estendida, enquanto o conforto na condução torna suas viagens mais agradáveis. O design otimizado para estabilidade é ideal para motociclistas que buscam um estilo de condução touring. Com um índice de carga de 69 e um índice de velocidade V, este pneu é perfeito para a posição traseira de sua moto. Fabricado na Espanha, o Anakee 3 é um pneu sem câmara, com um diâmetro de roda de 17" e largura de seção de 3810 mm, ideal para quem valoriza qualidade e desempenho. Adquira já o seu e transforme suas aventuras sobre duas rodas!', 1400.43, 1269.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-820m5-mlc2rtpc9og74e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1680878209%2F58206085832', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257452920', 'Esmalte Colorama Coleção Diabo Veste Prada', 'OEsmalte Colorama Coleção O Diabo Veste Pradaé inspirado no glamour e sofisticação do universoda moda. Com a qualidade da Colorama, o esmalte oferece: Alta cobertura, com excelente pigmentação Brilho intenso e acabamento uniformeSecagem rápida, ideal para o dia a dia Longa duração, mantendo as unhas bonitas por mais tempo Perfeito para eventos, festas ou para quem gosta de unhas com visual marcante e sofisticado, esse esmalte combina com diferentes estilos e ocasiões. Modo de Uso: Comece com as unhas limpas e secas.Aplique uma camada de base.Passe uma camada do esmalte e aguarde secar.Aplique uma segunda camada para intensificar a cor.Finalize com top coat para maior brilho e durabilidade.', 18.12, 18.12, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-8261n-mm6hpnzzcgzza6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F58257452920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
