INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202106083', 'Esponja Minná Saboneteira Amarelo', '#html-body [data-pb-style=IP5AH76]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}A Esponja Minná Saboneteira Amarela traz mais praticidade e conforto para o seu banho. Com um compartimento exclusivo para sabonete, ela proporciona uma espuma cremosa e uma limpeza delicada, tornando a sua rotina de higiene mais eficiente e agradável Benefícios: ✔ Porta-sabonete integrado para mais comodidade ✔ Textura suave, ideal para todos os tipos de pele ✔ Produz espuma abundante, otimizando o uso do sabonete ✔ Formato ergonômico para melhor manuseio Desfrute de um banho revigorante e uma pele macia com a Esponja Minná Saboneteira Amarela! ????✨', 13.19, 13.19, NULL, 'Beauty > Bath & Body Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zuj-middzi7dg5c1fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F58202106083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22996995150', 'Loção Hidratante Corpo Monange Pele Extra Seca 400ml', 'Cuidar de nós mesmas é essencial para nos sentirmos bem. Para combater o ressecamento, OHidratante Desodorante Monange Hidratação Intensiva para Pele Extra Seca. Contém óleo com propriedades antioxidantes, lembrando você do cuidado com o corpo, mas sem esquecer da mente e do coração. Modo de Uso: Aplique aHidratante Desodorante Monange Hidratação Intensiva para Pele Extra Secaem todo corpo, após o banho ou sempre que desejar, massageando suavemente a pele até a sua completa absorção. #html-body [data-pb-style="646BA65A13CFE"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-size: Cover; background-attachment: Scroll; border-style: None; border-width: 1px; border-top-left-radius: 0px; border-top-right-radius: 0px; border-bottom-right-radius: 0px; border-bottom-left-radius: 0px; margin: 0px 0px 10px; padding: 10px; background-position: Left top; background-repeat: No-repeat no-repeat;}#html-body [data-pb-style="646BA65A13D13"]{border-style: None; border-width: 1px; border-top-left-radius: 0px; border-top-right-radius: 0px; border-bottom-right-radius: 0px; border-bottom-left-radius: 0px; margin: 0px; padding: 0px;}', 23.27, 23.27, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7rbl1-lmg6qbo37tcp45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22996995150', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098565177', 'Leave In Sérum Seda Luminous UV 110ml', '#html-body [data-pb-style=EY0NRFJ]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O Leave-in Seda Luminous UV 110ml é um finalizador capilar que oferece hidratação, proteção e brilho para os fios. Com 2% de Glycol e Vita C Complex, ele protege os cabelos contra os danos causados pelos raios UV, enquanto hidrata profundamente e proporciona um brilho intenso. O Leave-in Seda Luminous UV é perfeito para ser utilizado diariamente, mantendo os fios protegidos e com uma aparência saudável e radiante. Modo de Uso: Aplique uma pequena quantidade do Leave-in Seda Luminous UV nos cabelos úmidos ou secos, do comprimento às pontas, evitando a raiz. Não é necessário enxaguar. Modele como desejar. Pode ser utilizado diariamente para garantir proteção e brilho aos fios.', 33.36, 33.36, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7raux-mal8v6rvwh2uac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23098565177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
