INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198994024', 'Condicionador Tio Nacho Engrossador E Antiqueda 415 Ml', 'O Condicionador Tio Nacho Antiqueda Engrossador possui uma combinação exclusiva da geléia real com Capilgross, Extratos de origem natural, aumentando a espessura do fio, evitando a queda, proporcionando brilho, volume e um cabelo mais forte, saudável. Além do aumento na espessura dos fios, fortalece o couro cabeludo retirando os fios opacos e quebradiços. Modo de uso: Após lavar os cabelos, aplique sobre o cabelo ainda molhado, fazendo uma leve massagem, e deixe agir por alguns minutos. Enxágue. #html-body [data-pb-style="646BA654A611F"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA654A6133"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 67.6, 67.6, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnhbbe6pcedr8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20198994024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
