INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297750041', 'Balcão de Canto Cozinha 100% MDF sem Tampo Sevilha Herval Azul/Órion Azul', 'O Balcão de Canto Cozinha 100% MDF Sem Tampo Sevilha Herval é perfeito para otimizar espaços com praticidade e elegância. Produzido em MDF de 15 mm, oferece resistência, durabilidade e excelente acabamento. Conta com dobradiças com amortecimento, proporcionando fechamento suave e silencioso, além de puxadores ponto metálicos, que valorizam o design do móvel. Possui também sapatas niveladoras, garantindo maior estabilidade e melhor ajuste ao piso. Sua montagem flexível permite instalar a porta do lado esquerdo ou direito do módulo, adaptando-se ao ambiente. Tampo vendido separadamente. Estilo: Moderno Modular: Sim Peso (kg): 26.25 Garantia: 06 Meses Altura (cm): 86.5 Acabamento: Pintura UV Largura (cm): 92.5 Possui Pés: Rodapé Possui Portas: Sim Tipo de Porta: Bater Altura dos Pés: 14 Pés Reguláveis: Não Possui Gavetas: Não Possui Rodízio: Não Suporta Até (kg): 20 Acompanha Tampo: Não Profundidade (cm): 52 Suporta Granito: Sim Escala de Brilho: Semi-Brilho Material dos Pés: MDF Tipo de Base (pés): Rodapé Cesto para Frutas: Não Material da Porta: MDF Origem do Produto: Nacional Acabamento dos Pés: Pintura Ambiente Principal: Cozinha Balcão Suporta Pia: Não Material Principal: MDF Possui Prateleiras: Sim Acabamento da Porta: Pintura Sapatas Niveladoras: Sim Balcão Acompanha Pia: Não Material da Prateleira: MDF Acabamento da Prateleira: Pintura Texturizada UV Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Tipo de Puxador da Porta: Externo Escala de Brilho da Porta: Semi-Brilho Peso Máximo por Prateleira: 5 Acompanha Rodapé Decorativo: Sim Possui Recorte para Cooktop: Não Material do Puxador da Porta: Alumínio Escala de Brilho da Prateleira: Semi-Brilho Tipo de Dob