INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42628604276', 'Cromo Redux 60 caps Picolinato de Cromo Bodyaction', 'CROMO REDUX 250 INGREDIENTES: Cromo (Picolinato de Cromo) e Antiumectante. INGREDIENTES DA CÁPSULA: Gelatina, Água potável filtrada e Corantes Azul Brilhante, Azorrubina e Dióxido de Titânio. NÃO CONTÉM GLÚTEN. SUGESTÃO DE USO: Sugere-se a ingestão de 1 (uma) cápsula 1 (uma) vez ao dia, ou conforme orientação de nutricionista ou médico para satisfazer suas necessidades diárias. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo de luz. Não consumir o produto se o lacre de proteção estiver violado. Após aberto, consumir preferencialmente em 90 dias.', 69.9, 25.0, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-82628-mkcpm8r8vuh370', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F338537405%2F42628604276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698883087', 'Câmera de Ré 4K Borboleta 2x1 Com Linha Dinâmica JR8', 'Câmera de Ré 4K Borboleta 2x1 Com Linha Dinâmica JR8 Câmera de ré 4K borboleta 2x1 Função linha dinâmica para manobras seguras Instalação prática e compatível com diversos veículos Garantia oficial de 3 meses A Câmera de Ré 4K Borboleta 2x1 JR84KDINAM é ideal para aumentar a segurança nas manobras. oferece imagens nítidas e detalhadas, além da função de linha dinâmica, que auxilia na orientação durante o estacionamento. O design borboleta permite instalação discreta e compatível com diversos modelos de veículos. Segurança: visão clara e precisa ao dar ré Tecnologia: resolução 4K com linhas dinâmicas Compatibilidade: instalação em diferentes veículos Praticidade: modelo borboleta de fácil fixação Durabilidade: construção resistente para uso diário Por que escolher este produto? Porque a câmera JR84KDINAM combina alta definição com praticidade, oferecendo mais confiança e segurança nas manobras. É a escolha certa para quem busca modernizar o veículo com tecnologia acessível. Dúvidas Frequentes; Serve em qualquer carro? Sim, é universal e pode ser instalada em diversos modelos. A linha dinâmica acompanha o movimento do volante? Sim, ela ajusta a projeção conforme o giro da direção. É resistente à chuva? Sim, possui proteção contra intempéries. O que vem na caixa 1 Câmera de Ré 4K Borboleta 2x1 Linha Dinâmica Cabos de conexão e acessórios de instalação Garantia e Envio Garantia oficial de 3 meses Postagem em até 24h após a compra', 179.9, 179.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/br-11134207-820lg-mlzcfvh0ohs43e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F94608