INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599566516', 'TENSOR CORREIA MB SPRINTER 311 313 413 415 515 2.2 16V ALTERNADOR', 'APLICAÇÃO: MERCEDES-BENZ: ACCELO 715C OM 612 2001 EM DIANTE SPRINTER 2.2 2001 EM DIANTE SPRINTER 313 OM611 2.2 16V 2001 ATÉ 2012 SPRINTER 413 OM611 2.2 16V CDI 2001 ATÉ 2012 CARACTERISTICAS: TIPO: TENSOR DA CORREIA MEDIDA EXTERNA: 70MM LARGURA: 26MM OFFSET: 53,5MM REFERÊNCIA: 30326 SCH / DYV837 DAYCO / A6112000570 OEM FAVOR CONSULTAR O VENDEDOR SE REALMENTE É COMPATÍVEL COM SEU VEÍCULO! • VALOR UNITÁRIO • PRODUTO NOVO E ORIGINAL • ENVIO DO PEDIDO COM NOTA FISCAL • COM GARANTIA DE FÁBRICA • ANTES DE EFETUAR O PEDIDO, FAVOR TIRAR AS DÚVIDAS NO CAMPO DE PERGUNTAS CUIDAR DO SEU CARRO DE MANEIRA PREVENTIVA GERA ECONOMIA E, ACIMA DE TUDO, GARANTE SUA SEGURANÇA PARA DIRIGIR TRANQUILO. A NOVA VIA TRABALHA PARA OFERECER O MELHOR EM AUTOPEÇAS, COM UM ESTOQUE DE MAIS DE VINTE MIL ITENS, PARA QUE VOCÊ ENCONTRE SEMPRE O QUE PRECISAR. DISTRIBUÍMOS AUTOPEÇAS DAS MAIORES E MELHORES MARCAS DO MERCADO, COM UM ATENDIMENTO QUALIFICADO DE PROFISSIONAIS QUE ATUAM HÁ MAIS DE VINTE ANOS NO SEGMENTO. NOVA VIA AUTOPEÇAS: SEMPRE O MELHOR PARA SEU CARRO!', 243.26, 231.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rfgn-m4armfla2m9taa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F714090968%2F21599566516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897485239', 'Óculos de natação Invictus Speedo - PRETO AMARELO', 'Obtenha excelente desempenho (performance) usando óculos Speedo INVICTUS. Modelo com vedação suave (softouch), que evita marcas no rosto e praticidade do ajuste fácil das tiras. Projetado com tecnologia “soft frame”, que integra ventosa, moldura e narizeira, proporcionando excepcional conforto durante sessões de treinamento e segurança nas competições outdoor (águas abertas, maratonas aquáticas e triathlon). Indicado para nadadores frequentes, que buscam conforto e tecnologia aliados à durabilidade. ÁRea de vedação tamanho M (a vedação ocorre abaixo das sobrancelhas). Com proteção UV e tratamento antiembaçante (anti-fog). Para escolher a lente ideal (verifique disponibilidade no modelo desejado): Cristal: Visão clara sem mudar a aparência das cores. Comum para uso em diversos ambientes. Amarelo: Eliminam o azul do espectro de cores, deixando tudo mais brilhante. Ideal para utilização em ambientes fechados. Azul: Reduz o reflexo e permite clara visão. Ideal para uso em ambientes abertos e fechados. Fumê: Reduz a transmissão de luz, diminuindo a luminosidade. Ideal para utilização em ambientes abertos. Vedação SofTouch sem demasiada pressão no rosto Ventosa em TPE (elastômero termoplástico), com vedação macia e confortável, ideal para não deixar marcas no rosto Tira repartida, de silicone, com easy adjust, perfeita para atletas iniciantes e amadores, pela facilidade de ajuste Flexnose: Narizeira flexível, melhor adaptação aos diferentes formatos de rosto Lentes curvas que ampliam o campo de visão Lentes em policarbonato Lente com Antifog: Evita o embaçamento das lentes para prolongar a excelente visão Proteção UV: Os raios UVA e UVB são reconhecidos como os mais danosos emitidos pelo sol. As lentes de nossos óculos contêm substâncias que absorvem a luz UV (390nm a 400nm). Embalagem: Elipse Box Área de Vedação: M – A vedação ocorre abaixo das sobrancelhas, com foco em conforto e média cobertura facial. Para melhor conservação, mantenha as lentes livres de poeira e gordura. Lave suavemente com água limpa e fria após o uso, deixando secar à sombra. Não esfregue ou passe pano nas lentes, para não danificá-las. Lembre-se: Faça o teste de sucção antes de usar. Pressione os óculos de natação junto aos olhos até atingir o efeito de leve sucção. Se os óculos aderirem a sua face momentaneamente, indicará um bom ajuste. E os seus óculos vem com películas protetoras sobre as lentes – remova antes de usar. Atenção: Exceto quando em uso, evite deixar os óculos expostos ao sol ou temperaturas muito altas. Proteja sempre as lentes dos seus óculos para evitar possíveis danos. Tratamento antiembaçante: É Aconselhável a colocação dos óculos ainda secos e evitar molhar o interior das lentes, pois o acúmulo de cloro pode danificar esta propriedade, que sofre desgaste natural no uso. Para manutenção, recomendamos o uso periódico do Anti-fog Speedo nas lentes, prolongando a propriedade antiembaçante. Importante: Não mergulhe na água usando óculos de natação incorretamente. Não nade abaixo de 2 metros de profundidade. Os óculos são para uso na superfície da água. ÓCulos de natação não protegem os olhos de lesão em caso de choque ou impacto, sempre preste atenção ao seu redor quando estiver usando. O contato com protetores solares ou produtos abrasivos danificam suas lentes. Em caso de irritação na pele, suspenda o uso imediatamente. Crianças não devem utilizar este produto sem a presença e supervisão de um adulto. Garantia contra defeitos de fabricação: 90 dias. Prazo de validade indeterminado.', 159.9, 159.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/sg-11134201-7rd5f-luqoo0v5mh6842', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242944993%2F23897485239', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
