INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28880965463', 'Mini Câmera de Segurança A9 HD Wi-fi Preto com Sensor de Movimento 110V e Suporte para Encaixe', 'Mini Câmera de Segurança A9 HD Wi-fi com Sensor de Movimento 110V e Suporte para Encaixe JORTAN Especificações do produto: Material: Liga de alumínio. Resolução de vídeo: 1980 x 1080p. Formato de vídeo: AVI. Tipo de cartão de memória: Suporta cartões micro SD de até 128GB (TF não incluso). Suporte ao aplicativo: iOS / Android. Itens unitários inclusos: - 1 Câmera A9 Mini. - 1 Mini suporte de metal com encaixe para a câmera. - 1 Cabo USB. - 1 Manual de instruções. Especificações Técnicas Visão Noturna: 6 LEDs infravermelhos 940nm / F3 | Distância de iluminação: 5 metros. Formato de Vídeo: ASF. Ângulo de Visão: 90° a 150°. Suporte de Rede: Wi-Fi 2.4 GHz (Não Suporta Redes 5GHz). Áudio (Captação): Até 5m. Corrente de Carga: 240 mA. Taxa de Quadros: 16 FPS. Alimentação: 3.7 V. Codificação de Vídeo: H.264. Armazenamento: Suporta cartão TF (Micro SD) de até 128 GB. Temperatura de Operação: -10°C a 50°C.', 99.99, 29.99, NULL, 'Cameras & Drones > Security Cameras & Systems > CCTV Security Cameras', 'https://cf.shopee.com.br/file/sg-11134201-824hd-melt3n0fptdt85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363055219%2F28880965463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3792523676', 'Alto Falante Triton Tr 850 Rms 12 Polegadas 1700 Watts Rms - 4 Ohms', '# OESTESOM # TR850, é um alto-falante com 1700 W de programa musical foi desenvolvido para reprodução de uma ampla faixa de frequência, na tecnologia empregada, utiliza anéis estabilizadores (Shorting Rings) no conjunto magnético que reduzem a distorção harmônica e estendem a resposta de frequência em todos níveis de potência, deixando mais eficiente o ponto de transição entre o alto falante e o drive fenólico. Carcaça em alumínio injetado com sistema de ventilação integrado para melhor dissipação de calor, o conjunto do motor desenvolvido através de software de modelamento em elementos finitos que garantem linearidade das linhas de campo magnético. Seu conjunto móvel conta com uma bobina de poliamida de alta temperatura e fio CCAW que melhora a condução da corrente, permitindo aplicação de potência elevada, e centragem impregnada com materiais que ajuda a restaurar e prolongar sua vida útil. Cone desenvolvido em celulose com a adição de compostos, assim deixando-o mais resistente e exclusivo, mantendo a fidelidade na resposta de frequência do produto, resultando em um alto SPL de 95,6 dB e uma baixíssima compressão de potência e compressão dinâmica. Este produto obtém um ótimo resultado em Caixas Trio, Sistemas 3 Vias e Trio Elétrico. Especificações Técnicas Diâmetro nominal:12º Impedância nominal: 4 ohms Resposta em frequência: 58 Hz a 3600 Hz Potência de programa musical:1700W Sensibilidade 1W/1m: 95,6 dB SPL Parâmetros Thielle-Small Potência RMS : 850 W Fs: 79 Hz Re: 3 ohms Qes: 0,48 Qms: 8,83 Qts: 0,45 Vas: 22,8 litros Sd: 531,4 cm? Xmax: 8,5mm Mms: 69,59 gramas Bl:14,69 Tm Le: 0,24 mH (10kHz) No: 2,26 %o Informações complementares Material do ímã: ————————— Ferrite de Bário Dimensão do ímã: ———————— 200 x 24 mm Material da carcaça: ——————— Alumínio Material do fio da bobina: ————— CCAW Secção do fio da bobina: —————- Circular Material da forma da bobina: ———– Kapton Material do cone: ————————- Celulose Importante: A *OESTESOM* recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 1063.33, 945.52, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/0edbf8981420d6c739b23337e9734c9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F3792523676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47709948104', 'Pasta Edição Sabores 3x3 Banana cor Amarela com 20 Folhas BRA - BC-2017', 'Pasta BRA foi desenvolvida para organizar e preservar seus cards com segurança e praticidade. Produzida com material de alta qualidade, ela conta com 20 folhas plásticas frente e verso, cada uma com 18 bolsos com entrada lateral, totalizando capacidade para armazenar até 360 cartas no formato padrão 65x88mm. O design moderno garante maior proteção contra poeira, umidade e desgaste, mantendo suas cartas bem conservadas. A pasta é leve, resistente e perfeita para colecionadores que valorizam tanto a estética quanto a funcionalidade no armazenamento de seus cards.Entrada lateral para maior segurança dos cards - Proteção prática e durável - Design temático da linha Edição Sabores – Banana. Características:- Marca:BRA- Modelo:BC-2017*Imagens Meramente Ilustrativas*Conteúdo da Embalagem: 01 Pasta BRA 3x3 Edição Sabores. Contém 20 folhas (Capacidade até 360 Cards).', 116.35, 97.9, NULL, 'Stationery > Others', 'https://cf.shopee.com.br/file/sg-11134201-820o0-mnueenk2qpz5d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F47709948104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
