INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51701001180', 'Brinquedo Infantil Blocos de Montar Caminhão de Bombeiros 260 Peças Xalingo - 16198', 'O Caminhão de Bombeiros Xalingo é um empolgante brinquedo de montar com 260 peças, perfeito para crianças que adoram o universo dos bombeiros e das missões de resgate. Com design inspirado em veículos reais de emergência, o conjunto permite construir um caminhão cheio de detalhes, estimulando a imaginação e proporcionando horas de diversão. Indicado para crianças acima de 6 anos, o brinquedo é compatível com outros blocos da coleção Xalingo, permitindo ampliar as construções e criar novas histórias de ação. Um brinquedo criativo, educativo e cheio de emoção — ideal para pequenos heróis em formação. Ficha técnica Dimensões Aproximadas (AxLxC): 20x6x25cm Idade Recomendada: A partir de 6 anos. Quantidade de peças: 160 Peso do produto: 218g Características: - Marca:Xalingo - Modelo:16198 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - Blocos de Montar Caminhão de Bombeiros 260 Peças Xalingo', 138.08, 120.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-821ef-mgsayt077f9qa8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F51701001180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29789338197', 'Sandália Feminina Lumiss Flatform Confortável Tiras Fivela Enfeite Metalizado Marsala', 'Estilosa e cheia de atitude, essa sandália flat traz tiras cruzadas e design moderno com detalhe nos dedos e aplique metalizado dourado. O acabamento em material sintético de brilho suave e o fechamento no tornozelo garantem firmeza e conforto ao caminhar. Um modelo que atualiza instantaneamente qualquer look casual com um toque fashion. ..:::.. ESPECIFICAÇÕES DO PRODUTO ..:::.. *Material - Napa Sintética *Solado - PVC Expandido, Emborrachado, Anti-derrapante, Não faz barulho, Não escorrega. *Altura do salto - 4,5 cm *Altura da frente - 3,5 cm. *Palmilha - Confortável com aplique da logo. Medida aproximada dos pés para cada numeração: Tamanho 34 --- 23,0 cm Tamanho 35 --- 24,0 cm Tamanho 36 --- 24,5 cm Tamanho 37 --- 25,0 cm Tamanho 38 --- 26,0 cm Tamanho 39 --- 26,5 cm Tamanho 40 --- 27,0 cm SOBRE A LUMISS: Desde 2018, brilha no coração da Lumiss a inovação para calçados femininos. Nascida como Amorelle, a marca é fruto do sonho de um visionário que sempre acreditou na possibilidade de fabricar calçados que surpreendessem o mercado, tanto pela variedade quanto por seus preços acessíveis. Com muito trabalho em família, essa ideia foi levada adiante, fortalecendo uma marca que hoje é referência nacional em calçados femininos, com presença marcante nos marketplaces e mais de dois milhões de pares já entregues em todo o Brasil. Comprometida com cada cliente, a Lumiss oferece as maiores tendências do mundo da moda a partir de materiais que garantem conforto, qualidade, sofisticação e estilo aos pés da mulher brasileira, encantando até mesmo os perfis mais exigentes. Além disso, a empresa se preocupa em oferecer a melhor experiência de compra, com total segurança e praticidade. Lumiss é mais que uma marca. É uma ideia que chegou para mostrar que todas as mulheres podem brilhar e ser ainda mais lindas e confiantes com calçados que as valorizam em todos os aspectos.', 199.9, 99.9, NULL, 'Women Shoes > Wedges', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mctnt9u88dmp4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323760756%2F29789338197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57655415976', 'Kit Lápis Hb Unicórnio - 2 Lapis/Apontador/Borracha Leo&Leo Leonora - 10544', 'O kit é composto de materiais básicos e necessários para as atividades em sala de aula, com ótimas opções para a criança se desenvolver e aprender de maneira alegre, saudável e estimulada. Detalhe: todos os itens são estampados com o personagem. Com 4 itens, o kit inclui: 2 Lápis grafite nº 2 com borracha na ponta / HB mina de 2,2 mm macia e resistente; 1 Apontador com depósito e 1 Borracha com formato. Dá para desenhar, escrever, apagar e apontar tudo o que for pedido nas atividades da escola e no dever de casa. O Kit Lápis HB Unicórnio 2 Lápis/Apontador/Borracha além de atóxico, é o parceiro certo para os momentos inesquecíveis de aprendizagem de todas as crianças, ajudando, de forma lúdica e imaginativa, a se transformarem em estudantes criativos e alegres. FICHA TÉCNICA: - 2 Lápis HB; - 1 Apontador com depósito; - 1 Borracha com formato; - Medidas do Produtos: Borracha: 4cm x 3,17cm / Lápis HB: 0,7cm x 18,5cm x 0,7cm / - Apontador: 2,5cm x 4cm x 1,5cm; - Composição: Lápis Grafite: Corpo em resina, virola de alumínio e borracha em resina plástica. Apontador: Resina termoplástica e lâmina em aço inox. Borracha: Isenta de PVC, carga inerte e pigmentos atóxicos. Características: - Marca:Leonora - Modelo:10544 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Kit Lápis Hb Unicórnio - 2 Lapis/Apontador/Borracha', 14.56, 13.25, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-82617-mjzzf59ov0g719', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F57655415976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
