INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997420797', 'Condicionador Kolene Original 500Ml', 'Condicionador Kolene é ideal para os fios capilares que necessitam de recuperação, devolve a vitalidade aos cabelos. Promove resultado imediato, já que os ativos essenciais presentes na fórmula proporcionam hidratação intensiva e completa para os cabelos indisciplinados e opacos. Modo de uso: Após o uso do shampoo, coloque uma pequena quantidade de condicionador na palma da mão e esfregue-as brevemente. Passe as mãos suavemente no comprimento até as pontas. Espere 2 minutos, enxague com água fria para finalizar. #html-body [data-pb-style="646BA64810449"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA6481045F"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 33.72, 33.72, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7rblz-lmg4qwrnf3mrb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F19997420797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
