INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42973430289', 'Engate Rápido Para Mangueira Com Aquastop 1/2'''' (78508/000) - Tramontina', 'O Engate Rápido Para Mangueira Com Aquastop 1/2'''' (78508/000) - Tramontina, é uma peça que possibilita a ligação entre a mangueira, torneira e acessórios de forma muito mais prática, permitindo trocar os acessórios mesmo com a torneira aberta. Um item indispensável para seu jardim! Descrição do Produto: • Produto fabricado com matéria-prima de alta qualidade proporcionando uma irrigação precisa e confiável. • Utilizado na saída de água da mangueira. • Conexão por sistema de fixação rosqueado à mangueira de 1/2". • Com sistema Aquastop, que bloqueia a saída de água ao remover o acessório. • Conexão tipo click aos acessórios de irrigação, através de 2 garras. Referência: 78508/000. Cód. de Fábrica: 78508/000. Marca: Tramontina.', 9.9, 9.9, NULL, 'Home & Living > Gardening > Irrigation Systems', 'https://cf.shopee.com.br/file/sg-11134201-824il-mfn0b2yf8cg892', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F42973430289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
