INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54206306355', 'Mini Pirulito Psicodélico Colorido C/50 Unidades 250g Santa Rita', 'Esses mini pirulitos são a escolha perfeita para festas, lembrancinhas e eventos especiais. Com seu visual divertido e sabor irresistível, eles encantam crianças e adultos. Feito com ingredientes de alta qualidade, o pirulito psicodélico não só traz um toque nostálgico como também é um sucesso garantido em qualquer celebração. 🍭 Ingredientes: Açúcar, xarope de glicose, contém: corantes aritificiais: amarelo tartrazina, azul brilhante FCF e vermelho 40. Aromatizante artificial de tutti-frutti. NÃO CONTÉM GLÚTEN. ALÉRGICOS: CONTÉM TARTRAZINA E PODE CONTER TRAÇOS DE SOJA. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacados em doces com lojas físicas no estado de São Paulo, desde 2002.', 16.99, 16.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-81zte-mkxvg0dytxc106', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F54206306355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
