INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299579996', 'Mop Spray Limpa Vidros com Reservatório de Água', 'O Limpa Vidros é feito para tirar poeiras e marcas de dedos de forma mais simples. Para utiliza-ló, basta aplicar o produto de limpeza no reservatório do borrifador e, então, usar a flanela macia para esfregar. Na hora de limpar as janelas, o ideal é que você comece pelas bordas da esquadeia e depois parta para o vidro em si. BENEFÍCIOS: -Um produto completo, 3 em 1 -Pano de microfibra -Esfrega, limpa e dá brilho -Borrifador: Utilize água ou o produto de preferência -Rodinho: Remove o excesso e seca - Sistema de limpeza em spray INFORMAÇÕES TÉCNICAS: Cor: Azul com Cinza Medida: 7cm X 25cm X 26cm Composição: Alumínio / ABS / PP / POM / Borracha / Microfibra (80% Poliéster, 20% Poliamida e Pigmento)', 34.88, 33.14, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m53gj1ekarm8e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F539308905%2F20299579996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
