INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898378858', 'Jasmine Cookies Ameixa Preta E Coco Zero Açúcar 120G', 'O Cookie Zero é feito com Stévia natural, polpa de coco brasileiro e granfibra farinha de trigo integral elaborada no moinho de pedra da Jasmine, processo que preserva os nutrientes dos grãos de trigo e mantém a integridade do sabor. Além disso, é vegan e extremamente saboroso!. Ingredientes: Farinha de trigo integral, farinha integral reconstituída de trigo, farinha de trigo enriquecida com ferro e ácido fólico, óleos vegetais (milho e/ou girassol e/ou algodão e/ou palma), fibra solúvel, ameixa, coco, amido, alfarroba em pó, edulcorantes naturais maltitol e glicosídeo de esteviol, fermentos fosfato monocálcico, bicarbonato de sódio e bicarbonato de amônio, emulsificante natural lecitina de soja, aromas e antioxidante natural tocoferol. ALÉRGICOS: CONTÉM DERIVADO DE TRIGO E DE SOJA. PODE CONTER AVEIA, CENTEIO, CEVADA, AVELÃ, AMÊNDOA, AMENDOIM, CASTANHA-DE-CAJU, CASTANHA-DO-PARÁ, MACADÂMIA, NOZ, PECÃ, PISTACHE, PINOLI E CASTANHAS. CONTÉM GLÚTEN. O GLÚTEN É PREJUDICIAL À SAÚDE DOS DOENTES CELÍACOS.', 14.05, 14.05, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-7rene-m86jxv1tff6qfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F22898378858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28085900208', 'Amend Cachos Fluído Revitalizador Day After - 190ml', 'Fluído Revitalizador Day After Amend Cachos 190ml Revitalize seus cachos no day after com definição, brilho e maciez instantâneos O Fluído Revitalizador Day After Amend Cachos é a solução prática e eficaz para recuperar a forma dos cachos no dia seguinte à lavagem. Ideal para todas as curvaturas, sua fórmula com 12 óleos nutrifuncionais ativa a memória dos fios, reativando a curvatura natural com hidratação, definição e leveza, sem pesar. Destaques do produto: Ativa a memória dos cachos e reaviva a curvatura natural Elimina o frizz e reduz o ressecamento Brilho, maciez e definição instantâneos Fórmula com 12 óleos vegetais altamente nutritivos 100% vegano e indicado para todos os tipos de cachos Composição nutritiva com 12 óleos: Argan, Karité, Algodão, Coco, Macadâmia, Camomila, Aloe Vera, Chá Verde, Mirra, Cálamo, Oliveira e Canela – uma mistura poderosa que trata profundamente os fios enquanto revitaliza. Conteúdo: 190ml | Sem enxágue Modo de uso: Com os cabelos secos, pulverize o fluido a uma distância de 20 cm até obter a umidade desejada. Modele com as mãos ou finalize como de costume. Precauções: Uso externo. Evite contato com os olhos. Mantenha fora do alcance de crianças. Dê vida nova aos seus cachos todos os dias com praticidade! Garanta já o Fluído Day After Amend Cachos e mantenha seus fios definidos e incríveis em qualquer momento!', 49.9, 36.68, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9bkz8d11536b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1077804858%2F28085900208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
