INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099702493', 'Richée BB Cream - Nutrição 12ml - Ampola Power Dose', 'Aminoácidos da seda e creatina. BB Cream Protein Restaurador Condicionante, transforma seus cabelos em minutos. Com ação instantânea, nutre os cabelos, deixando-os macios, brilhantes e com aspecto saudável. Modo de uso: AGITE ANTES DE USAR. Após lavar os cabelos com Shampoo, retire o excesso de água e aplique o produto sobre as mãos, que devem estar levemente molhadas. Friccione-as até formar espuma e, em seguida, espalhe por todo o comprimento e pontas dos fios, enluvando bem mecha a mecha. Deixe agir de 3 a 5 minutos e enxágue bem. Finalize como desejar. Precauções: Uso externo. Mantenha fora do alcance das crianças. Evite contato com os olhos. Em caso de contato com os olhos, enxágue abundantemente com água. Em caso de irritação, suspenda o uso e procure orientação médica. Conservar em local fresco ao abrigo da luz.', 20.7, 16.56, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5388yzmue1101', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513541030%2F18099702493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
