INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998986525', 'Par Amortecedor Dianteiro Perfect Palio Weekend Siena Palio', 'Este anúncio contém os seguintes produtos: 01 Amortecedor Dianteiro Lado Direito Perfect; 01 Amortecedor Dianteiro Lado Esquerdo Perfect; Atenção: Produtos Novos e Originais, com 1 ano de garantia de fábrica. Código do produto: AMD0122; Referencias: COFAP: GP30120 GP30126 NAKATA: HG33093 Observação: Prato pequeno; Aplicação dos Veículos: Montadora: Fiat; Veículo: Palio - ( Exceto novo Palio ) Motor: 1.0, 1.3, 1.4, 1.5, 1.6, 1.8; Ano de fabricação: 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016; Montadora: Fiat; Veículo: Palio Weekend; Motor: 1.0; Ano de fabricação: 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010; Montadora: Fiat; Veículo: Siena; Motor: 1.0, 1.3, 1.4, 1.5, 1.6, 1.8; Ano de fabricação: 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010; Fabricante: O fabricante do amortecedor Perfect é conhecido por sua especialização em produtos de suspensão automotiva, focando na qualidade e inovação. Seguem rigorosos padrões de qualidade e testes para garantir a durabilidade e performance dos seus produtos. Sobre Nós A Jb Autopeças, Fundada Em 1980, é uma empresa referência no mercado de autopeças, oferecendo soluções completas para veículos nacionais e importados. Com mais De 40 Anos de experiência, nossa equipe especializada proporciona atendimento personalizado e consultivo para atender às necessidades específicas de cada cliente. Com mais De 30.000 itens em estoque dos melhores fabricantes, estamos prontos para oferecer a solução Ideal que o seu carro precisa. Temos por missão, fornecer autopeças de alta qualidade, com excelência em serviço e entrega, garantindo satisfação total aos nossos clientes. Nossa equipe está comprometida com: 1. Compromisso Com A Qualidade. 2. Excelência No Atendimento. 3. Inovação Contínua. 4. Ética E Transparência. Garantia de fábrica: 1 anos', 511.41, 511.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfk1zk34an7p7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1017593623%2F22998986525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198793427', 'Brinco Rommanel Banhado Ouro Pequeno Coração Vazado 526499', 'Este brinco Rommanel, banhado a ouro 18k, é uma peça delicada e elegante. Com formato de coração vazado, é uma joia que combina com qualquer ocasião. Seu tamanho é de 0,7 cm x 1,0 cm, perfeito para quem gosta de brincos pequenos, mas que não passam despercebidos. Este brinco faz parte da coleção 2020 - 1º ciclo da Rommanel, uma marca reconhecida pela qualidade e beleza de suas peças. O fecho do tipo borboleta garante segurança e conforto ao usar. A cor amarela do ouro 18k dá um toque de sofisticação e a cor principal dourada combina com diversos estilos. Apesar de não ter pedras, o design vazado do coração é o que dá charme a esta peça. Este modelo é feminino e vem em um kit com duas unidades. Se você gosta de joias delicadas e com significado, este brinco Rommanel é a escolha perfeita.', 115.9, 90.0, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134201-820mb-mr2vyo55osnae4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1593190827%2F22198793427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297597486', 'Pote Hermético Cristal (PP+PET) Retangular 1,2L Oxford Grey', 'A Oxford oferece uma grande variedade de potes para facilitar o armazenamento de alimentos no dia a dia. O pote Cristal (PP+PET) com fechamento hermético é leve e fácil de manusear. A peça vem com instruções ilustradas para fechamento e abertura da tampa, bem como sugestão de uso. Tudo para deixar sua cozinha ainda mais organizada! Conteúdo da embalagem: 1 Pote Hermético Cristal (PP+PET) Retangular 1,2L Grey - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Forma: Retangular - É apto para lava-louças: Não - Formato de venda: Unidade - Cor: Cinza - Altura: 21,9 cm - É hermético: Sim - Largura: 11,6 cm - Material: Polipropileno e Polietileno Tereftalato - Com tampa: Sim - É apto para micro-ondas: Não - Modelo: Pote Hermético - Capacidade em volume: 1,2 L - Unidades por embalagem: 1 ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 53.29, 53.29, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rd41-lwrf11z3vg6dee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075271269%2F23297597486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
