INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397555657', 'Pneu Firestone Aro 18 Destination LE3 265/60R18 110H', 'Marca: FIRESTONE Modelo: DESTINATION LE3 Medida: 265/60R18 Largura: 265 Perfil: 60 Tamanho de Aro: 18 Índice de peso: 110 - 1060 kg Índice de velocidade: H - 210 km/h Tipo de Veiculo: SUV Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Simétrico UTGQ: N/A Adesão à àgua: C Eficiência energética: C Ruído externo: 71 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores Sobre a marca Firestone A marca Firestone foi fundada em Ohio nos Estados Unidos, 1900. Há mais de um século os pneus Firestone equipam veículos com alta qualidade e segurança. A confiabilidade de utilizar um pneu bom, seguro e acessível, faz dos pneus Firestone uma ótima opção para o seu veículo, seja para lazer ou trabalho. Com diversas linhas disponíveis, sem dúvida uma delas vai atender à sua necessidade, com a garantia da experiência de uma marca tradicional no mercado de pneus e a garantia de utilizar o que há de melhor no desenvolvimento de pneus.', 983.88, 888.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-lw4gc4xrudun1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23397555657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
