INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251977066', 'Maionese Heinz Tradicional', 'A Maionese Heinz Tradicional é cremosa, saborosa e contém ovos caipiras, que dão a ela um sabor inigualável. Perfeita para sanduíches, batatas fritas e hambúrgueres, é a escolha ideal para deixar seus pratos ainda mais gostosos. A textura e consistência da maionese Heinz provém da emulsão de ovos e óleo. Leve e fácil de espalhar, não contém amido nem glúten. * Marca que mais cresceu em preferência do consumidor em 2018. * Contém ovos de galinha caipira.', 14.79, 14.79, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-825b2-mqneljuuhix79d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554783%2F58251977066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798142197', 'Espátula Pizza Tramontina Utilitá Em Aço Inox Cabo Preto', 'Espátula para Pizza Tramontina Utilitá em Aço Inox com Cabo de Polipropileno Preto - Praticidade e Elegância para Seus Momentos! Seja no jantar em família ou no happy hour com os amigos, a Espátula para Pizza Tramontina Utilitá é indispensável na sua cozinha. Produzida com lâmina em aço inox de alta resistência e cabo em polipropileno preto, ela combina funcionalidade, durabilidade e design moderno. Seu formato ergonômico e prático facilita o manuseio, permitindo servir suas pizzas com precisão e elegância. Resistência e Durabilidade: A lâmina de aço inox garante desempenho superior, sendo resistente ao uso frequente e à corrosão. Praticidade no Dia a Dia: Pode ir à máquina de lavar louças, economizando seu tempo. Design Funcional: O cabo em polipropileno possui um furo passante, ideal para pendurar e organizar sua cozinha. Elegância e Versatilidade: Harmoniza com qualquer decoração de mesa, tornando seus momentos ainda mais especiais. Com dimensões de 263x70x34 mm, a espátula é compacta e fácil de guardar, garantindo praticidade sem ocupar espaço desnecessário. Ideal para servir pizzas grandes e pequenas com estilo e eficiência. Respostas às Suas Perguntas: "A espátula é resistente?" Sim, sua lâmina de aço inox é altamente resistente e durável, mesmo com uso frequente. "É fácil de limpar?" Sim, pode ser lavada manualmente ou na máquina de lavar louças. "O cabo é confortável?" Sim, o cabo de polipropileno é ergonômico, proporcionando conforto e firmeza no uso. "Posso pendurar a espátula?" Sim, o cabo possui um furo passante para facilitar o armazenamento. Transforme o ato de servir pizza em uma experiência sofisticada e prática com a Espátula para Pizza Tramontina Utilitá. Compre agora e surpreenda nos seus melhores momentos!', 49.99, 45.99, NULL, 'Home & Living > Kitchenware > Spatulas & Cooking Tweezers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m54n4hyb0dde62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333246733%2F22798142197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
