INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393677843', 'Aditivo Impermeabilizante Concreto e Argamassa 900ml - Vedacit', 'VEDACIT VEDACIT é um aditivo impermeabilizante para concretos e argamassas, que age por hidrofugação do sistema capilar e permite a respiração dos materiais, mantendo os ambientes salubres. ÁREAS DE APLICAÇÃO Estruturas • Muro de Arrimo e Paredes de Encosta • Concreto • Alicerce, Baldrame e Sapatas Áreas Frias e de Serviços • Cozinha • Lavanderia • Banheiros Áreas Externas • Paredes Reservatórios • Muro de Arrimo e Paredes de Encosta • Concreto Piscinas • Enterrada Áreas Internas • Paredes MODO DE APLICAÇÃO Uso de poucas ferramentas e pouca dificuldade de aplicação Preparo e aplicação Você pode consultar mais detalhes abaixo de como preparar o produto para uso. Características Densidade: 1,05 g/cm³ Composição básica: Silicatos Rendimento: • Balde de 18 L: até 9 sacos de cimento (50kg) Preparação do Substrato As estruturas que serão impermeabilizadas com argamassa devem estar suficientemente dimensionadas e sem trincas. Já as superfícies a serem revestidas devem estar chapiscadas e limpas. "VEDACIT: Um aditivo indispensável para qualquer projeto de construção."', 44.9, 22.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5lufywivd5ce5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F705932885%2F22393677843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
