INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250693200', 'CAPACETE MOTO ORIGINAL LS2 FF358 S DIGITAL PRETO AMARELO', 'Produto acompanha apenas a viseira Cristal - Foto meramente ilustrativa. A nova versão do FF358 se chama CLASSIC S, com um design mais aerodinâmico, moderno e agressivo; devido ao seu spoiler que vem integrado ao casco. Sendo ideal para os motociclistas que buscam conforto e praticidade no dia a dia. Suas linhas aerodinâmicas foram inspiradas nos capacetes de alto desempenho e sua forma oval diminui o arrasto e potencializa a circulação de ar. CARACTERÍSTICAS: • Sua tecnologia tornou-se referência em cascos desenvolvidos em ABS, sendo classificado com 4 estrelas Sharp, pelo órgão britânico que adota os mais rigorosos padrões de segurança mundial; •O FF358 CLASSIC S possui ótimo campo de visão, com sistema de troca rápida; •Viseira de policarbonato de excelente qualidade e ótima resistência; •Construído em ABS de alta qualidade, este spoiler traseiro deixa o seu FF358 CLASSIC S ainda mais estiloso e possui as saídas de ar sob ele; •O tipo de fecho é o engate micrométrico, para travar o capacete e é diretamente ligado com a cinta jugular; •Cortado à laser, o forro interno é respirável, antibacteriano e removível para lavagem.', 879.9, 695.13, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-821d5-mh6npegl68zz30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F58250693200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45811340362', 'AGULHA DO PISTONETE COM SEDE DO CARBURADOR TMAC TITAN 150 KS ES ESD 04 A 08', 'Agulha do Pistonete com Sede do Carburador TMAC para motos Honda CG 150 Titan KS / ES / ESD e CG 150 Job, compatível com modelos de 2004 até 2008. Peça desenvolvida para proporcionar melhor desempenho na alimentação de combustível, auxiliando na regulagem correta do carburador e no funcionamento estável do motor. Fabricada com materiais de alta resistência e excelente acabamento, garantindo maior durabilidade e eficiência. Aplicação: • Honda CG 150 Titan KS – 2004 a 2008 • Honda CG 150 Titan ES – 2004 a 2008 • Honda CG 150 Titan ESD – 2004 a 2008 • Honda CG 150 Job – 2004 a 2008 Características: • Marca: TMAC • Produto novo • Alta qualidade e resistência • Fácil instalação • Excelente custo-benefício Conteúdo da embalagem: • 1 Agulha do pistonete com sede do carburador Ideal para reposição e manutenção do carburador, ajudando no melhor desempenho da motocicleta e na economia de combustível.', 9.9, 9.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-823q7-mosyh65t9s7591', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F45811340362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
