INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10927849003', 'Tapete Comfort de Yoga Macio,1,2cm de Espessura, 1,80m de Comprimento, Verde, T54, Acte Sports', '•ANTIDERRAPANTE – Tapete Confort Acte Sport é produzido em NBR, garantindo macies ao produto. A parte em contato com o solo é microondulada, possui alta aderência o que torna os exercícios mais seguros e a parte superior possui textura aveludada &nbsp; •ALÇA DE TRANSPORTES - Possui alça de transporte para que você leve o produto para aonde desejar, podendo ser utilizado em casa, em parques, academias, estúdios, praças entre outros lugares, mantendo o tapete protegido e bem conservado &nbsp; •DO TAMANHO IDEAL– Medindo 1,80m de comprimento, 1,2cm de espessura e 60cm de largura você terá o tapete de Yoga do tamanho ideal para realizar o seu treino, com qualidade e resistência, mantendo o seu corpo confortável e protegido &nbsp; •CONFORTO E PROTEÇÃO -É ideal para praticar todos os exercícios de Yoga, Pilates e também durante a pratica de alongamento. Possui a função de proteger e tornar seguro o contato do corpo com o solo. Também pode ser utilizado juntamente com outros acessórios &nbsp; •SAÚDE E BEM ESTAR – O Tapete Confort Acte Sports proporciona segurança ao trabalhar os movimentos do seu corpo, permitindo o estímulo das articulações. A pratica do Yoga e Pilates ajuda na a respiração e concentração, reduzindo o nível de estresse &nbsp;', 174.9, 174.9, NULL, 'Sports & Outdoors > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfgu-m3cb7grp0c4g39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F424114018%2F10927849003', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27440992286', 'Espelho Lopazzi com Led Orgânico 150x40cm Grande Moderno Corpo Inteiro Pinterest Decoração Quarto Sala', 'Espelho Orgânico Magnus com LED 150x40 cm – Luz Quente e Fria, Vidro Lapidado Modernize seu ambiente com o Espelho Orgânico Magnus 150x40 com LED. Com design funcional e acabamento sofisticado, é ideal para banheiros, salões de beleza, consultórios, quartos e escritórios. Além de proporcionar iluminação precisa, o espelho contribui para um visual clean e elegante, adaptando-se facilmente a diversos estilos de decoração. Benefícios do Produto: Design moderno e funcional: espelho retangular com bordas lapidadas que valorizam o ambiente Iluminação LED de alta performance: escolha entre luz quente (3000K) ou fria (6500K), conforme a necessidade Vidro resistente: material temperado de 3 mm com proteção contra impactos e riscos Instalação facilitada: suporte fixo e manual ilustrado para montagem rápida e segura Versátil e seguro: ideal para ambientes residenciais ou comerciais Especificações Técnicas; Dimensões: 150 cm de altura x 40 cm de largura Material: Vidro temperado lapidado, 3 mm de espessura Iluminação: LED com interruptor duplo (quente 3000K / fria 6500K) Alimentação: Bivolt (127V/220V) Garantia: 90 dias contra defeitos de fabricação Como Instalar: Fixe o suporte na parede utilizando os parafusos e buchas fornecidos, e pendure o espelho com cuidado. A superfície deve estar limpa, seca e nivelada para garantir a segurança da instalação. Embalagem Reforçada e Envio Seguro: O espelho é enviado com embalagem reforçada e materiais de proteção, garantindo que chegue em perfeito estado até você. Garantia do vendedor: 90 dias', 359.9, 329.9, NULL, 'Home & Living > Decoration > Mirrors', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me4qkuxsu1oi9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248180593%2F27440992286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293275194', 'Puff Redondo Preto', 'Que tal o Puff Redondo?Adicione mais estilo e comodidade no seu dia a dia com este lindo Puff Redondo. O produto é perfeito para leitura, tirar uma soneca ou assistir ao filme favorito e pode ser colocado no quarto ou na sala. Grande e espaçoso, ele acomoda muito bem quem for utilizá-lo e ainda dá um toque legal na decoração. Pode apostar que a atenção deste item será sempre disputada! Cor: Preto Garantia em Meses: 3 Cores do Produto: Preto Conteúdo da Embalagem: 1 Puff Redondo em Courino Preto Modelo: Redondo Número de Volumes: 1 Material: Confeccionado Em revestimento sintético De Alta Resistencia, Com Costura Tripla E Cheio Com Flocos De Isopor Material para Filtro: Revestimento Sintético Descrição do Tamanho: Altura: 75 cm | Largura: 85 cm | Profundidade: 85 cm Altura do Produto (cm): 75 Largura do Produto (cm): 85 Comprimento do Produto (cm): 85 Peso do Produto (Kg): 4.84 Produto precisa de Montagem?: Não Sofá-Cama: 0 Controle Remoto: 0 Desmontável: 0 Quantidade de Peças: 1 Tendências: Minimal Pop É giratório: Não Material da estrutura: Poliestireno Material do enchimento do assento: Flocos de Isopor Material do Revestimento: Revestimento Sintético Possui Baú?: Não Tipo de assento: Fixo Tipo de Puff: Gota PROFUNDIDADE x LARGURA x ALTURA: 85 x 85 x 75 Fornecedor: Correia & Santos Puff''s Design LTDA Baterias são necessárias?: Não Certificação de teste externa: Não Componentes incluídos: Não Is Fragile: Não Número da peça: Não Produto: Puff', 234.96, 224.36, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rcf5-m6e7w47dtn6i6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226120317%2F23293275194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
