INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399885539', 'Xicara De Café Chá Com Pires 185ml Santorini Porcelana Branca Tramontina', 'Xícara Tramontina Santorini em Porcelana – 185 ml A Xícara Tramontina Santorini é ideal para servir chá ou outras bebidas quentes com elegância e sofisticação. Produzida em porcelana tradicional de alta qualidade, possui acabamento fino, brilho delicado e decoração inspirada na clássica linha Santorini, que traz suavidade e charme à mesa posta. Características do produto: Capacidade: 185 ml Material: Porcelana de alta resistência, com baixa porosidade Design: Formato arredondado com alça confortável e estampa em tons suaves, acompanhando o estilo refinado da linha Santorini Acabamento: Brilhante, com queima controlada em alta temperatura, proporcionando resistência e toque suave Diferenciais: Porcelana higiênica, que não absorve líquidos ou odores Alta resistência ao uso diário Compatível com micro-ondas e lava-louças Ideal para compor conjuntos de mesa elegantes ou uso individual Cuidados recomendados: Lavar com esponja macia e sabão neutro Evitar o uso de abrasivos ou exposição direta a chamas Não utilizar em forno convencional', 59.9, 49.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-824im-mfb9qn5anbii69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349137150%2F21399885539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207779354', 'KIT NIVEA Hidratante Facial Beleza Radiante 7 em 1 100g + NIVEA Creme Facial Antissinais 100g', 'O que é? NIVEA Creme Facial Antissinais é um hidratante facial diário que reduz sinais e linhas de expressão. Para que serve? Com uma fórmula leve e de rápida absorção, este creme proporciona uma hidratação intensa de até 30 horas e o mais importante: sem deixar a pele com aspecto oleoso. Por possuir ingredientes hidro nutrientes e Vitamina E, NIVEA Creme Facial Antissinais previne as rugas, melhora a cicatrização e ainda protege a pele contra os raios UVA/UVB. Além disso, sua fórmula exclusiva firma a pele e ainda reduz linhas de expressão, deixando-a muito mais jovem e saudável. Benefícios e diferenciais - Firma e reduz linhas de expressão - Protege contra os raios UVA/UVB - Fórmula leve de rápida absorção - Hidratação intensa sem deixar a pele oleosa - Melhora a cicatrização O que é? NIVEA Creme Facial Uniformizador Beleza Radiante é um hidratante 7 em 1 desenvolvido para atender às necessidades da pele negra. Com uma fórmula inovadora, enriquecida com ácido hialurônico, extrato de pérolas e cúrcuma, reduz marcas escurecidas*, uniformiza o tom e ilumina a pele, garantindo hidratação profunda sem sensação oleosa. Para que serve? Oferece um cuidado completo: reduz marcas escurecidas*, uniformiza o tom, controla a oleosidade com efeito matte, ilumina e hidrata intensamente, realçando a beleza natural da pele negra. Benefícios e diferenciais: - Reduz marcas escurecidas - Uniformiza o tom da pele - Ilumina e hidrata - Controla a oleosidade com efeito matte - Com proteção uva/uvb - Desenvolvido para a pele negra', 83.8, 57.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134207-820lk-mmc3pq6i8e84cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F58207779354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13320393549', 'Película de Vidro Dupla para iPhone X e XS - Gorila Shield', 'A Película de Vidro Dupla , da Gorila Shield, é uma das mais fortes do mercado, possuindo o Certificado US Military. Fabricado com a melhor tecnologia disponível atualmente, o acessório possui 0,27mm de espessura para proteger a tela do seu aparelho sem alterar a sensibilidade. Além disso, a embalagem conta com duas películas, para que, em caso de riscos ou arranhões na tela, você tenha uma reserva para substituir imediatamente.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/2ea57a71d12e3ccbb00dbc793fd44265', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F13320393549', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
