INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49853376511', 'Kit 6 Bolas Tênis de Mesa 3 Estrelas Vollo Original', 'Bola Tênis de Mesa 3 Estrelas Vollo Modelo: VT611-VT612-3 A Bola de Tênis de Mesa Branca com 6 Unidades Vollo possui resistência, durabilidade e qualidade acima da média, graças aos rigorosos processos de fabricação que seguem as especificações técnicas das federações e confederações de tênis de mesa. Além de testes contínuos em laboratório que garante a excelência do produto. A bola de tênis de mesa com 3 estrelas dispõe de espessura, estabilidade e precisão ideal para criar partidas incríveis. Podendo ser utilizadas nos treinamentos mais avançados, em competições nacionais ou também durante treinos iniciantes, se você não abre mão de ter a melhor experiência. Garanta mais praticidade e rendimento durante os treinos com o kit de 6 bolas de ping-pong de alto nível da Vollo. Esta bola possui características que a tornam ideal para competições e jogadores exigentes. A classificação de 3 estrelas indica sua qualidade superior, garantindo um quique consistente, velocidade controlada e trajetória previsível. Isso permite que os jogadores aprimorem suas habilidades e alcancem desempenho máximo em suas partidas. Cores: Branco ou Laranja Projetada para desempenho superior e precisão Ideal para competição Peso e salto consistentes para jogo em ritmo acelerado Especificações: -Composição: ABS -Cor: Branca -Peso aproximado: 3g -Diâmetro: 40mm', 49.99, 29.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Table Tennis', 'https://cf.shopee.com.br/file/sg-11134201-81zuk-migcpizyp2pz16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1559054473%2F49853376511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
