INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259860369', 'Ração Quatree Para Gatos Life Filhotes Salmão e Arroz 10,1kg', 'DESCRIÇÃO:Especialmente desenvolvido para oferecer uma dieta saudável e nutritiva, Ração Seca Quatree Life Salmão e Arroz Gatos Filhotes é um alimento Premium Especial Natural formulado com antioxidantes naturais e complexo de vegetais para promover mais vitalidade e bem-estar para o seu gato. Indicado também para fêmeas durante o período de gestação até o desmame total dos filhotes. Não possui ingredientes transgênicos, corantes, aromatizantes e conservantes artificiais (BHT e BHA). BENEFICIOS: Crescimento saudável: Nutrientes essenciais para o desenvolvimento adequado. Apoio ao sistema imunológico: Fórmula enriquecida com vitaminas e minerais. Digestão otimizada: Ingredientes de fácil digestão que promovem um intestino saudável. QUANTIDADE RECOMENDADA: Filhotes até 2 meses: 50g a 100g/dia Filhotes de 2 a 4 meses: 100g a 150g/dia Filhotes de 4 a 6 meses: 150g a 200g/dia Filhotes de 6 a 12 meses: 200g a 250g/dia', 303.31, 181.96, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-820n3-mnnab8b95og050', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009890604%2F58259860369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41157691716', 'Goiabada Cascão Vovô Olavo 400g – Lata Redonda | Tradição Mineira Cremosa e Sabor Autêntico', 'A Goiabada Cascão Vovô Olavo 400g na lata é a escolha perfeita para quem aprecia o verdadeiro sabor das receitas mineiras. Feita em Ponte Nova – MG, leva apenas goiaba e açúcar, com textura cremosa e pedacinhos da fruta. A embalagem em lata redonda com tampa plástica conserva melhor o produto e carrega o charme das embalagens clássicas, sendo ótima tanto para o consumo direto quanto para presentear. ℹ️ Benefícios: ✅ Feita com goiaba e açúcar – sem conservantes ✅ Textura cremosa com pedaços de fruta ✅ Lata redonda tradicional com tampa plástica ✅ Sabor autêntico da goiabada mineira ✅ Ideal para acompanhar queijos, pães ou sobremesas ℹ️ Ficha Técnica: ✅ Produto: Goiabada Cascão Cremosa ✅ Marca: Vovô Olavo ✅ Peso: 400g ✅ Ingredientes: Goiaba e açúcar ✅ Glúten: Não contém ✅ Conservantes: Não contém ✅ Embalagem: Lata com tampa plástica ✅ Origem: Ponte Nova – Minas Gerais', 32.9, 32.9, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-7rdwa-mbx0kcxj7atp2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F41157691716', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21972832305', 'Kit C/ 5 Calcinha Microfibra Tanga Feminina Sortida', 'A Calcinha A43 é feita de Microfibra. Este modelo de calcinha é tanga e ideal para o seu dia a dia, se ajusta perfeitamente ao seu corpo, dando mais leveza e conforto no seu uso. - Tecido Leve em Microfibra - Viés aberto - Discreto, não marca na roupa - Boa durabilidade - Laterais levemente arqueadas Ótimo custo benefício! Lindas variações e opções de cores. Composição: 92% Poliéster 8% Elastano Tabela de tamanhos: P: 36 M: 38/40 G: 42/44 GG: 46 O Kit é enviado de forma sortida, podendo haver repetição de cores. A Compramais tem como missão desde 2013 proporcionar satisfação e qualidade para clientes em todo o Brasil. Trabalhamos com agilidade para garantir que seu pacote chegue com rapidez em suas mãos, no conforto do seu lar e sem precisar sair de casa! Temos um catálogo extenso de moda íntima que conta com itens femininos, masculinos e infantis. Ainda tem alguma dúvida? Nos faça uma pergunta! Compramais, paixão em moda íntima.', 47.25, 32.9, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-23020-1romsa148bnv51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328687466%2F21972832305', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
