INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498964233', 'Água Micelar Reequilibrante Melanina PhálleBeauty PH0729', 'A Água Micelar Reequilibrante é uma solução que auxiliará na limpeza profunda da pele de forma suave, removendo resíduos e a oleosidade facial. Seus ativos proporcionam, ainda, um reequilíbrio da pele, devolvendo viço, hidratação e nutrição à face. Benefícios: Remove e ajuda a controlar a oleosidade. 01. Un, contém 200ml.', 13.99, 13.99, NULL, 'Beauty > Makeup > Makeup Removers', 'https://cf.shopee.com.br/file/br-11134207-7r98p-llqhgvxznrjr1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F19498964233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
