INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891958365', 'Cavaco Eletrico Giannini Start Cs14 Preto Kit Capa + Paletas', 'Somos a Eletromusic Loja Especializada em Instrumentos Musicais a mais de 10 anos no Mercado. Qual e o nosso diferencial? A musica corre em nossas veias e por isso amamos o que fazemos, Buscamos sempre oferecer qualidade pelo Melhor preco.Todos os nossos produtos sao de Fornecedores Nacionais com rigoroso controle de qualidade, possuem nota fiscal eletronica e garantia de fabrica. Voce e bem vindo para fazer parte da nossa historia A nossa serie para quem esta iniciando na musica. Instrumentos aco e nailon com o melhor custo beneficio para todas as faixas etarias que estao aprendendo a tocar. Especificacoes: -Cavaco eletrico passivo sem regulagens -Tampo: Basswood -Lateral e Fundo: Basswood -Braco: Okoume -Escala: Sabina macica -Comprimento da escala: 340 mm (13,4") -Cavalete: Sabina macico -Tarraxas: Pino fino niqueladas, 2+2 -Pestana: ABS na cor marfim -Largura da pestana: 30 mm (1,2") -Rastilho: ABS na cor marfim -Largura do rastilho: 60 mm (2,4") -Acabamento: Verniz brilhante -Cordas: Calibre .011. Recomendamos para troca a Giannini Cobra CC82H, -Giannini Cobra GESCP -Headstock: Letra "S" holografica, placa adicional em basswood -Largura da caixa: 239 x 171 mm -Altura da caixa: 75 x 78 mm -Tamanho total: 60 cm (23,62")', 431.0, 431.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-820me-mlc7pd9e8yrqde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F22891958365', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
