INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697921144', 'Balcão de Escritório ME4149 c/ 2 Portas c/ Chave Preto - Tecno Mobili', 'Balcão de Escritório ME4149 c/ 2 Portas c/ Chave Preto - Tecno Mobili Marca: Tecno Mobili Dimensões(Cm): Comprimento(Profundidade): 36,5cm x Largura: 74,5cm x Altura: 60cm Material de Estrutura - Estrutura 100% MDP Tipo de Dobradiças - Dobradiças Metálicas Diferenciais das Gavetas - c/ Chave Tipo de Pintura - Pintura em UV (Ultravioleta) Tipo de Acabamento da Pintura - Pintura Semi Brilho Quantidade de Portas - 1 Porta de Abrir - 2 Portas de Abrir Quantidade de Gavetas - 1 Gaveta Quantidade de Prateleiras - 1 Prateleira Montagem do Produto - Desmontável Garantia - Garantia de 90 dias Certificação de Qualidade - Qualidade Aprovada Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 287.91, 273.52, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-82606-mmcd30uakphgb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F19697921144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799150729', 'Conjunto De Escritório Office 3 Peças Mesa Gaveteiro Balcão - Fendi E Freijó Fendi E Freijó', 'Conjunto De Escritório Office 3 Peças Mesa Gaveteiro Balcão - Fendi E Freijó Fendi E Freijó O Conjunto de Escritório Tundra é uma opção completa para aprimorar seu ambiente de trabalho. O Balcão Tundra traz versatilidade e elegância para seu espaço. Estrutura em MDP de 25 mm, garante durabilidade e resistência. Possui puxadores embutidos em MDF, 4 portas, divisão interna que conta com 2 prateleiras para acomodar todos os itens de escritório, como documentos e objetos pessoais. O Gaveteiro Tundra é ideal para organização, estrutura em MDP de 25 mm com gavetas de corrediças telescópicas, uma delas para itens diversos e outra para pastas suspensas. Os puxadores são usinados em MDF com bordas laqueadas e rodízios de silicone para fácil movimentação. A Mesa de Escritório Tundra é prática e elegante, com estrutura em MDP de 25 mm, tampo duplo chanfrado em MDP e MDF, bordas laqueadas, distanciadores e sapatas niveladoras cromadas para maior conforto no trabalho. ESPECIFICAÇÕES TÉCNICAS: - Material: MDP/MDF; - Material do Tampo: Tampos duplos MDP25 e MDF 15mm; - Material estrutura: MDP 25mm - Possui Portas: Sim, em MDF chanfrado; - Puxadores: Usinados nas portas e gavetas c/ acabamento laqueado; - Possui Prateleiras : Sim; - Possui Gavetas: Sim, 2(duas) no gaveteiro com corrediça telescópica; - Possui Nicho: Sim; - Rodízios: sim, 4 de silicone no gaveteiro; - Possui sapatas: Sim, niveladoras cromadas na mesa e no balcão; - Produto Precisa de Montagem? Sim; - Garantia: 3 Meses; - Medidas Balcão (LarguraXProfundidadeXAltura): 180x43x80cm - Medidas Mesa (LarguraXProfundidadeXAltura): 160x68x80cm - Medidas Gaveteiro (LarguraXProfundidadeXAltura): 48,5x43x66,5cm Altura da Mesa (cm): 80cm | Quantidade de caixas de embalagem: 4 | Altura do Gaveteiro (cm): 65cm | Altura do Balcão (cm): 80cm | Largura da Mesa (cm): 160cm | Largura do Gaveteiro (cm): 48,5cm | Largura do Balcão (cm): 180cm | Profundidade da Mesa (cm): 68cm | Profundidade do Gaveteiro (cm): 43cm | Profundidade do Balcão (cm): 43cm | Altura dos Pés (cm): Não se aplica | Ambiente Principal: Escritório | Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem | Cor do Produto: Fendi/Freijó | Cor Predominante: Fendi | Cor Interna: Fendi | Acabamento da Gaveta: Pintura UV | Acabamento dos Pés: Silicone | Escala de Brilho: Fosco | Escala de Brilho da Gaveta: Fosco | Bandeja: Não | Possui gavetas: Sim | Estilo: Moderno | Acabamento: Pintura UV | Garantia: 3 meses | Itens Inclusos: 1 Mesa, 1 Gaveteiro, 1 Balcão, Manual de Montagem e Kits de Montagem | Marca: ViaNossa | Linha ou Coleção: Tundra | Inclui manual de montagem: Sim | Material da Gaveta: MDP/MDF | Material dos Pés: Silicone | Cor: Fendi e Freijó', 2479.0, 2479.0, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-821f4-mgi3o5pwetcd1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22799150729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
